#define NBOOT_TOGGLES ((unsigned)(sizeof BOOT_TOGGLES / sizeof BOOT_TOGGLES[0]))

/*
 * Compound names: one word that resolves to several rows.
 *
 * -g and -B predate the table and each already meant more than one thing, so
 * they stay compound rather than being quietly narrowed. A short form has no
 * negative spelling and therefore only ever enables, exactly as today; a long
 * form gets the usual --name / --no-name pair.
 */
static const struct {
    const char *token;       /* "-g", or "jailbreak" for --jailbreak      */
    bool        long_form;   /* true: --token / --no-token; false: literal */
    const char *members[4];  /* NULL-terminated list of BOOT_TOGGLES names */
    const char *help;
} BOOT_COMPOUND[] = {
    { "-g", false, { "framebuffer", "iomfb-display", "mbx", NULL },
      "graphics experiment: --framebuffer --iomfb-display --mbx" },
    { "-B", false, { "baseband", "spi2", NULL },
      "leave the whole baseband transport matched: --baseband --spi2" },
    { "jailbreak", true, { "jb-codesign", "jb-payload", NULL },
      "both jailbreak halves at once: --jb-codesign --jb-payload" }
};

#define NBOOT_COMPOUND \
    ((unsigned)(sizeof BOOT_COMPOUND / sizeof BOOT_COMPOUND[0]))

/* Effective values plus where each one came from, so a run can report its own
 * configuration instead of leaving a reader to reconstruct it from argv and a
 * memory of what the defaults were that week. */
typedef struct {
    boot_toggles_t v;
    signed char    req[NBOOT_TOGGLES];  /* -1 unset, 0 asked off, 1 asked on */
    const char    *by[NBOOT_TOGGLES];   /* the argv token that asked         */
} boot_config_t;

static bool *boot_toggle_slot(boot_toggles_t *t, unsigned row) {
    return (bool *)(void *)((unsigned char *)t + BOOT_TOGGLES[row].offset);
}

static bool boot_toggle_value(const boot_toggles_t *t, unsigned row) {
    return *(const bool *)(const void *)
           ((const unsigned char *)t + BOOT_TOGGLES[row].offset);
}

static void boot_config_defaults(boot_config_t *cfg) {
    memset(cfg, 0, sizeof *cfg);
    for (unsigned i = 0; i < NBOOT_TOGGLES; i++) {
        *boot_toggle_slot(&cfg->v, i) = BOOT_TOGGLES[i].def;
        cfg->req[i] = -1;
        cfg->by[i]  = NULL;
    }
}

static int boot_toggle_index(const char *name) {
    for (unsigned i = 0; i < NBOOT_TOGGLES; i++)
        if (!strcmp(BOOT_TOGGLES[i].name, name)) return (int)i;
    return -1;
}

/* Last-wins is right for a value like -c and wrong for a switch: "-g --no-mbx"
 * reads as a coherent request and is not one. Refuse both directions of the
 * same row rather than let argument order decide silently. */
static bool boot_toggle_request(boot_config_t *cfg, unsigned row, bool on,
                                const char *token) {
    if (cfg->req[row] >= 0 && (cfg->req[row] != 0) != on) {
        fprintf(stderr,
                "%s: contradicts the earlier %s -- --%s cannot be both "
                "enabled and disabled in one run\n",
                token, cfg->by[row], BOOT_TOGGLES[row].name);
        return false;
    }
    cfg->req[row] = on ? 1 : 0;
    if (!cfg->by[row]) cfg->by[row] = token;
    *boot_toggle_slot(&cfg->v, row) = on;
    return true;
}

/* Exact --name / --no-name match. Built by comparison rather than by
 * formatting a candidate string, so there is no buffer to size and nothing for
 * -Wformat-truncation to reason about. */
static bool boot_long_match(const char *arg, const char *name, bool *on) {
    if (!arg || !name || !on || strncmp(arg, "--", 2)) return false;
    const char *rest = arg + 2;
    bool negated = false;
    if (!strncmp(rest, "no-", 3)) { negated = true; rest += 3; }
    if (strcmp(rest, name)) return false;
    *on = !negated;
    return true;
}

typedef enum {
    BOOT_TOGGLE_NOT_MINE = 0,   /* some other option; keep parsing */
    BOOT_TOGGLE_ACCEPTED,
    BOOT_TOGGLE_REJECTED
} boot_toggle_parse_t;

static boot_toggle_parse_t boot_toggle_parse(const char *arg,
                                             boot_config_t *cfg) {
    if (!arg || !cfg) return BOOT_TOGGLE_NOT_MINE;

    /* Compounds first. A compound means MORE than any one row -- -g has always
     * implied -F and v_display=1 as well as keeping MBX matched -- so if a
     * token could be read either way, reading it as the single row would
     * silently narrow a command line that already exists in the run logs.
     * boot_toggle_table_selfcheck() refuses such an overlap outright; this
     * order means that even if one were introduced it would fail safe. */
    for (unsigned c = 0; c < NBOOT_COMPOUND; c++) {
        bool on = true;
        if (BOOT_COMPOUND[c].long_form) {
            if (!boot_long_match(arg, BOOT_COMPOUND[c].token, &on)) continue;
        } else if (strcmp(arg, BOOT_COMPOUND[c].token)) {
            continue;
        }
        for (unsigned k = 0; BOOT_COMPOUND[c].members[k]; k++) {
            int row = boot_toggle_index(BOOT_COMPOUND[c].members[k]);
            if (row < 0) {
                fprintf(stderr,
                        "internal error: compound %s names unknown toggle %s\n",
                        BOOT_COMPOUND[c].token, BOOT_COMPOUND[c].members[k]);
                return BOOT_TOGGLE_REJECTED;
            }
            if (!boot_toggle_request(cfg, (unsigned)row, on, arg))
                return BOOT_TOGGLE_REJECTED;
        }
        return BOOT_TOGGLE_ACCEPTED;
    }

    for (unsigned i = 0; i < NBOOT_TOGGLES; i++) {
        const boot_toggle_t *row = &BOOT_TOGGLES[i];
        bool on = false;
        bool matched = boot_long_match(arg, row->name, &on);
        if (!matched && row->on_alias && !strcmp(arg, row->on_alias)) {
            matched = true;
            on = true;
        }
        if (!matched && row->off_alias && !strcmp(arg, row->off_alias)) {
            matched = true;
            on = false;
        }
        if (matched)
            return boot_toggle_request(cfg, i, on, arg)
                       ? BOOT_TOGGLE_ACCEPTED : BOOT_TOGGLE_REJECTED;
    }
    return BOOT_TOGGLE_NOT_MINE;
}

/*
 * Self-check the table itself.
 *
 * Two rows sharing a bool, two rows claiming the same alias, or a short flag
 * that is both a compound and a single row all resolve a command line to
 * something other than what it says -- and that is precisely the class of bug
 * this layer exists to remove, so it is checked rather than reviewed. The
 * compound/alias collision is not hypothetical: -g was written as an alias of
 * --mbx first, which quietly dropped the -F and v_display=1 that -g has always
 * also meant.
 */
static bool boot_alias_collides(const char *token) {
    if (!token) return false;
    for (unsigned i = 0; i < NBOOT_TOGGLES; i++)
        if ((BOOT_TOGGLES[i].on_alias &&
             !strcmp(BOOT_TOGGLES[i].on_alias, token)) ||
            (BOOT_TOGGLES[i].off_alias &&
             !strcmp(BOOT_TOGGLES[i].off_alias, token)))
            return true;
    return false;
}

static bool boot_toggle_table_selfcheck(void) {
    bool ok = true;
    for (unsigned i = 0; i < NBOOT_TOGGLES; i++) {
        const boot_toggle_t *a = &BOOT_TOGGLES[i];
        if (!a->name || !*a->name || !a->help || a->group >= BOOT_GROUP_COUNT ||
            a->offset >= sizeof(boot_toggles_t))
            ok = false;
        /* A name beginning "no-" would make --no-<name> ambiguous. */
        if (a->name && !strncmp(a->name, "no-", 3)) ok = false;
        if (a->on_alias && a->off_alias && !strcmp(a->on_alias, a->off_alias))
            ok = false;
        for (unsigned j = i + 1; j < NBOOT_TOGGLES; j++) {
            const boot_toggle_t *b = &BOOT_TOGGLES[j];
            if (!strcmp(a->name, b->name) || a->offset == b->offset) ok = false;
            const char *mine[2]  = { a->on_alias, a->off_alias };
            const char *yours[2] = { b->on_alias, b->off_alias };
            for (unsigned p = 0; p < 2; p++)
                for (unsigned q = 0; q < 2; q++)
                    if (mine[p] && yours[q] && !strcmp(mine[p], yours[q]))
                        ok = false;
        }
    }
    for (unsigned c = 0; c < NBOOT_COMPOUND; c++) {
        if (!BOOT_COMPOUND[c].token || !*BOOT_COMPOUND[c].token ||
            !BOOT_COMPOUND[c].members[0] || !BOOT_COMPOUND[c].help)
            ok = false;
        /* A token that is both a compound and a row alias reads as whichever
         * loop runs first. Refuse it rather than depend on that order. */
        if (!BOOT_COMPOUND[c].long_form &&
            boot_alias_collides(BOOT_COMPOUND[c].token))
            ok = false;
        if (BOOT_COMPOUND[c].long_form &&
            boot_toggle_index(BOOT_COMPOUND[c].token) >= 0)
            ok = false;
        for (unsigned k = 0; BOOT_COMPOUND[c].members[k]; k++)
            if (boot_toggle_index(BOOT_COMPOUND[c].members[k]) < 0) ok = false;
    }
    /* Every row's default must round-trip through a fresh resolve, and a
     * fresh resolve must record that nothing was asked for. */
    boot_config_t probe;
    boot_config_defaults(&probe);
    for (unsigned i = 0; i < NBOOT_TOGGLES; i++)
        if (boot_toggle_value(&probe.v, i) != BOOT_TOGGLES[i].def ||
            probe.req[i] != -1)
            ok = false;
    /* And --name / --no-name must reach that row and only that row. */
    for (unsigned i = 0; i < NBOOT_TOGGLES && ok; i++) {
        for (unsigned pass = 0; pass < 2; pass++) {
            boot_config_t t;
            boot_config_defaults(&t);
            char spelled[128];
            size_t n = strlen(BOOT_TOGGLES[i].name);
            const char *lead = pass ? "--no-" : "--";
            size_t lead_n = strlen(lead);
            if (lead_n + n + 1u > sizeof spelled) { ok = false; break; }
            memcpy(spelled, lead, lead_n);
            memcpy(spelled + lead_n, BOOT_TOGGLES[i].name, n + 1u);
            if (boot_toggle_parse(spelled, &t) != BOOT_TOGGLE_ACCEPTED) {
                ok = false;
                break;
            }
            for (unsigned j = 0; j < NBOOT_TOGGLES; j++) {
                bool want = j == i ? (pass == 0) : BOOT_TOGGLES[j].def;
                if (boot_toggle_value(&t.v, j) != want) ok = false;
                if ((t.req[j] >= 0) != (j == i)) ok = false;
            }
        }
    }
    return ok;
}

static void boot_print_indented(FILE *out, const char *prefix,
                                const char *text) {
    for (const char *p = text; p && *p; ) {
        const char *nl = strchr(p, '\n');
        size_t n = nl ? (size_t)(nl - p) : strlen(p);
        fprintf(out, "%s%.*s\n", prefix, (int)n, p);
        if (!nl) break;
        p = nl + 1;
    }
}

/* The whole point of generating this from the table is that help cannot drift
 * from behaviour: a row with no help line, or a default that disagrees with the
 * code, is now impossible rather than merely unlikely. */
static void boot_print_toggle_help(FILE *out) {
    for (unsigned g = 0; g < BOOT_GROUP_COUNT; g++) {
        fprintf(out, "\n  %s\n", BOOT_GROUP_TITLE[g]);
        for (unsigned i = 0; i < NBOOT_TOGGLES; i++) {
            const boot_toggle_t *row = &BOOT_TOGGLES[i];
            if (row->group != g) continue;
            fprintf(out, "    %-4s--%s / --no-%s",
                    row->def ? "ON" : "off", row->name, row->name);
            if (row->on_alias)  fprintf(out, "   [%s enables]", row->on_alias);
            if (row->off_alias) fprintf(out, "   [%s disables]", row->off_alias);
            fputc('\n', out);
            boot_print_indented(out, "         ", row->help);
        }
    }
    fputs("\n  compound aliases  (one word, several rows above)\n", out);
    for (unsigned c = 0; c < NBOOT_COMPOUND; c++) {
        if (BOOT_COMPOUND[c].long_form)
            fprintf(out, "    --%s / --no-%s\n",
                    BOOT_COMPOUND[c].token, BOOT_COMPOUND[c].token);
        else
            fprintf(out, "    %s  (enables only; it has no negative form)\n",
                    BOOT_COMPOUND[c].token);
        boot_print_indented(out, "         ", BOOT_COMPOUND[c].help);
    }
}

/* The value-taking options as they are resolved, so --print-config can report
 * the whole machine description and not just its booleans. */
typedef struct {
    const char *kernel_path;
    const char *dtpath;
    const char *cmdline;
    const char *rdpath;
    const char *external_md_source;
    const char *external_md_work;
    const char *restore_path;
    const char *fstab_line;
    const char *jailbreak_payload;
    const char *rd_form;
    uint32_t    phys_base, virt_base, ram_size, rd_grow_mb;
    const uint32_t *hot_page;            /* hot_page_n entries; -H is repeatable */
    unsigned    hot_page_n;
    uint64_t    steps, win_lo, win_hi, heartbeat;
    unsigned    ba_rev, ba_ver, ktail, nsnaps, ncall_probes, ndtov, ntouch;
    unsigned    ndrags, nbuttons;
    /* --ppp appends a boot argument, and it does so AFTER --print-config has
     * already exited. Without this the printed cmdline would be the one the
     * operator typed rather than the one the guest gets, and a reader would
     * reasonably conclude the DMA skip was never applied. */
    bool        ppp;
    bool        nat;
} boot_values_t;

static void boot_print_config(FILE *out, const boot_config_t *cfg,
                              const boot_values_t *val) {
    fputs("S5LBox resolved configuration\n", out);
    fputs("  (\"default\" means nothing on this command line asked for it)\n",
          out);
    for (unsigned g = 0; g < BOOT_GROUP_COUNT; g++) {
        fprintf(out, "\n  %s\n", BOOT_GROUP_TITLE[g]);
        for (unsigned i = 0; i < NBOOT_TOGGLES; i++) {
            if (BOOT_TOGGLES[i].group != g) continue;
            fprintf(out, "    %-20s %-4s %s",
                    BOOT_TOGGLES[i].name,
                    boot_toggle_value(&cfg->v, i) ? "on" : "off",
                    cfg->req[i] < 0 ? "default" : "command line");
            if (cfg->req[i] >= 0 && cfg->by[i])
                fprintf(out, " (%s)", cfg->by[i]);
            fputc('\n', out);
        }
    }
    fputs("\n  values\n", out);
    fprintf(out, "    %-20s %s\n", "kernel",
            val->kernel_path ? val->kernel_path : "(none)");
    fprintf(out, "    %-20s 0x%08x\n", "phys-base", val->phys_base);
    fprintf(out, "    %-20s 0x%08x\n", "virt-base", val->virt_base);
    fprintf(out, "    %-20s %u MB\n", "ram", val->ram_size >> 20);
    fprintf(out, "    %-20s %" PRIu64 "\n", "steps", val->steps);
    fprintf(out, "    %-20s %s\n", "devicetree",
            val->dtpath ? val->dtpath : "(none)");
    fprintf(out, "    %-20s \"%s\"\n", "cmdline",
            val->cmdline ? val->cmdline : "");
    if (val->ppp)
        fprintf(out, "    %-20s %s\n", "",
                "+ uart4_dma_enable=0 (appended by --ppp unless already "
                "present)");
    fprintf(out, "    %-20s %s\n", "ramdisk",
            val->rdpath ? val->rdpath : "(none)");
    fprintf(out, "    %-20s %s\n", "external-md source",
            val->external_md_source ? val->external_md_source : "(none)");
    fprintf(out, "    %-20s %s\n", "external-md work",
            val->external_md_work ? val->external_md_work : "(none)");
    fprintf(out, "    %-20s %s\n", "restore",
            val->restore_path ? val->restore_path : "(none)");
    fprintf(out, "    %-20s %u\n", "snapshot-at count", val->nsnaps);
    fprintf(out, "    %-20s \"%s\"\n", "fstab",
            val->fstab_line ? val->fstab_line : "");
    fprintf(out, "    %-20s %u MB\n", "grow", val->rd_grow_mb);
    fprintf(out, "    %-20s %s\n", "ramdisk address", val->rd_form);
    fprintf(out, "    %-20s %s\n", "jailbreak payload",
            val->jailbreak_payload ? val->jailbreak_payload : "(none)");
    fprintf(out, "    %-20s rev %u ver %u\n", "boot_args", val->ba_rev,
            val->ba_ver);
    fprintf(out, "    %-20s [%" PRIu64 ",%" PRIu64 ")\n", "profile window",
            val->win_lo, val->win_hi);
    fprintf(out, "    %-20s %" PRIu64 "\n", "heartbeat", val->heartbeat);
    fprintf(out, "    %-20s", "hot pages");
    for (unsigned i = 0; i < val->hot_page_n; i++)
        fprintf(out, " 0x%08x", val->hot_page[i]);
    fputc('\n', out);
    fprintf(out, "    %-20s %u\n", "abort trace lines", val->ktail);
    fprintf(out, "    %-20s %u\n", "call probes", val->ncall_probes);
    fprintf(out, "    %-20s %u\n", "touch taps", val->ntouch);
    fprintf(out, "    %-20s %u\n", "drag gestures", val->ndrags);
    fprintf(out, "    %-20s %u\n", "button presses", val->nbuttons);
    fprintf(out, "    %-20s %u\n", "-D overrides", val->ndtov);
}

/*
 * Two lines in the run header, so a log describes the run that produced it.
 *
 * Runs record argv in their manifest, which is only self-describing while the
 * defaults never move. Replaying an old argv against a newer binary can mean
 * something different, and docs/BOOTLOG.md has roughly sixty entries whose
 * reading depends on what the defaults were that day. These lines record the
 * RESOLVED values, so the log is readable without knowing the binary:
 *
 *   config     : name=0|1 ...   every toggle, effective value, table order
 *   config-cli : names          only what this command line actually asked for
 */
/*
 * The exact command line, quoted so it can be pasted back.
 *
 * This exists because the two lines below are NOT sufficient to reproduce a
 * run, and twice now that has cost a boot. `config-cli` names toggles only: it
 * says nothing about -c, -d, -r, -R, --external-md or --snapshot-at. run72 and
 * run89 were both reconstructed from a `config-cli` line, both silently lost
 * `nand-enable-adm=0` from the kernel command line, and both died inside
 * AppleS5L8900XADMFMC::start about 218 million instructions in -- a failure
 * that looks like a guest bug and is actually a missing boot argument.
 *
 * A log that describes its own run must therefore carry the whole argv, not a
 * summary of part of it. This is the line to copy when reproducing a run;
 * `config` remains the line to READ when interpreting one, because argv alone
 * is only self-describing while the defaults never move.
 *
 * Quoting deliberately leaves backslashes alone. Every path on this host
 * contains them, and escaping them would make the common case unreadable, be
 * wrong for PowerShell and cmd, and be unnecessary for sh -- inside double
 * quotes sh only treats \ as an escape before $ ` " \ and newline, so a
 * Windows path survives verbatim. An argument is quoted only if it holds a
 * space, a tab or a quote; a quote is escaped; and a trailing backslash run is
 * doubled, which is the one case where an unescaped backslash would swallow
 * the closing quote.
 */
static void boot_argv_emit(FILE *out, int argc, char **argv) {
    fputs("relaunch   :", out);
    for (int i = 0; i < argc; i++) {
        const char *a = argv[i];
        bool quote = (*a == '\0') || strpbrk(a, " \t\"") != NULL;
        fputc(' ', out);
        if (!quote) { fputs(a, out); continue; }
        fputc('"', out);
        for (const char *p = a; *p; p++) {
            if (*p == '"') fputc('\\', out);
            fputc(*p, out);
        }
        for (const char *p = a + strlen(a); p > a && p[-1] == '\\'; p--)
            fputc('\\', out);
        fputc('"', out);
    }
    fputc('\n', out);
}

static void boot_config_emit(FILE *out, const boot_config_t *cfg) {
    fputs("config     :", out);
    for (unsigned i = 0; i < NBOOT_TOGGLES; i++)
        fprintf(out, " %s=%d", BOOT_TOGGLES[i].name,
                boot_toggle_value(&cfg->v, i) ? 1 : 0);
    fputc('\n', out);

    fputs("config-cli :", out);
    unsigned n = 0;
    for (unsigned i = 0; i < NBOOT_TOGGLES; i++) {
        if (cfg->req[i] < 0) continue;
        fprintf(out, " %s%s", cfg->req[i] ? "" : "no-", BOOT_TOGGLES[i].name);
        n++;
    }
    if (!n) fputs(" (none)", out);
    fputc('\n', out);
}

/*
 * Capabilities that are asked for and cannot be delivered yet.
 *
 * --activate defaults ON and --jailbreak's two halves default off, but none of
 * the three is implemented: two need an HFS+ file provisioner that does not
 * exist (tools/rootfs_work.c does size-neutral in-place rewrites only, and
 * data_ark.plist is not in the source rootfs), and the code-signing switch has
 * been traced but not built. The rule for all three is the same -- never fail
 * the run closed, because that would break every current workflow, and never
 * no-op silently, because a run whose header claims a configuration it did not
 * apply is worse than one that never offered the option.
 */
static void boot_capability_notes(FILE *out, const boot_config_t *cfg,
                                  bool external_md,
                                  const char *jailbreak_payload) {
    if (cfg->v.activate && external_md)
        fprintf(out,
                "activation : /var/root/Library/Lockdown/data_ark.plist will be "
                "provisioned with -ActivationState=FactoryActivated and "
                "-BrickState=false\n"
                "             (offline provisioning, not an Apple activation: "
                "no record is applied and none is verified)\n");
    else if (cfg->v.activate)
        fprintf(out,
                "activation : requested but NOT APPLIED -- provisioning needs a "
                "writable work image, i.e. --external-md\n");
    else
        fprintf(out,
                "activation : disabled by --no-activate; the guest keeps the "
                "ActivationState it shipped with\n");

    if (cfg->v.jb_codesign)
        fprintf(out,
                "jailbreak  : code-signing half APPLIED -- boot args gain "
                "cs_enforcement_disable=1 amfi_get_out_of_my_way=1\n"
                "             amfi_allow_any_signature=1, and "
                "/chosen/debug-enabled is set to 1\n"
                "             (applied, NOT demonstrated: nothing unsigned has "
                "been executed, and _cs_validate_page\n"
                "              fires either way because it is the kernel's "
                "page hasher, not AMFI's policy gate.\n"
                "              The deciding test is an unsigned binary that "
                "runs -- see --jb-payload.)\n");
    if (cfg->v.jb_payload) {
        fprintf(out,
                "jailbreak  : payload half requested but NOT APPLIED (no "
                "work-image file provisioning yet)\n");
        if (jailbreak_payload)
            fprintf(out,
                    "jailbreak  : payload %s verified readable but NOT USED\n",
                    jailbreak_payload);
        else
            fprintf(out,
                    "jailbreak  : no --jailbreak-payload given; there would be "
                    "nothing to install even once the provisioner lands\n");
    }
    if (!external_md && (cfg->v.activate || cfg->v.jb_payload))
        fprintf(out,
                "             (a writable work image means --external-md, and "
                "this run has none)\n");
}

typedef struct {
    uint64_t at;
    const char *path;
    bool done;
} boot_snapshot_request_t;

/* ------------------------------------------- external-md snapshot sidecars ---
 *
 * The core snapshot serialises s5l8900_t only, so none of the md bridges' host
 * state and none of the work image is in it. Rather than push host storage
 * concepts into the portable core, bootkernel writes two sidecars beside the
 * snapshot and owns their format entirely.
 *
 * What actually has to survive is small. In md_raw_bridge_t the config is
 * re-derivable from setup, scratch/iov_plan/data_spans are per-call transients,
 * and pending[] need only be empty; the exact-gated kernel patches and the four
 * bounce slots already live in guest RAM and therefore in the core snapshot.
 * That leaves the 128 KiB coherent allocation-tail overlay, the counters, and
 * the image contents at the checkpoint instant.
 *
 * Saving fails closed if any native-uiomove continuation is still pending: that
 * state spans a guest bounce slot and a host transfer, and a checkpoint taken
 * mid-flight could not be restored coherently.
 */
#define EXTERNAL_MD_SIDECAR_MAGIC UINT32_C(0x3144534d)   /* "MDS1" */
#define EXTERNAL_MD_SIDECAR_VERSION UINT32_C(1)

typedef struct {
    uint32_t magic;
    uint32_t version;
    uint64_t media_size;
    uint64_t image_bytes;
    md_bridge_stats_t strategy_stats;
    md_raw_bridge_stats_t raw_stats;
    uint8_t guard_tail[MD_RAW_BRIDGE_MAX_TRANSFER];
} external_md_sidecar_t;

/* Set during external-md setup so the checkpoint path can reach them. */
static md_bridge_t *g_external_strategy_bridge = NULL;
static md_raw_bridge_t *g_external_raw_bridge = NULL;
static file_block_t **g_external_adapter_slot = NULL;
static const char *g_external_work_image_path = NULL;
static uint64_t g_external_media_size_for_sidecar = 0;
/* Populated by a restore before the bridges exist, applied just after init. */
static external_md_sidecar_t g_external_restore_sidecar;
static bool g_external_restore_sidecar_valid = false;

/*
 * What /arm-io/i2s0/audio0 declares, and whether that settled a capture format.
 *
 * OUTSIDE `G` deliberately, for the same reason g_external_work_image_path is:
 * the tree is read while it is still in the harness's hands, and spy_install()
 * memsets the whole of G afterwards. A field here would be silently zeroed
 * between the read and every use of it -- which is exactly what happened when
 * these did live in G, and the run reported "no audio node" against a tree it
 * had just successfully read two rates out of.
 *
 * The decision is deferred to the FIRST SAMPLE rather than made here, because
 * at device-tree time the guest has not configured the controller yet and a
 * derivation then could only ever answer "unconfigured". g_audio_fmt_decided
 * separates "not evaluated" from AUDIO_FMT_OK, which is 0.
 */
static audio_dt_facts_t   g_audio_dt;
static bool               g_audio_dt_read = false;
static audio_format_t     g_audio_fmt;          /* valid only on ..._FMT_OK */
static audio_fmt_status_t g_audio_fmt_status = AUDIO_FMT_NO_NODE;
static bool               g_audio_fmt_decided = false;

static bool external_md_sidecar_path(char *out, size_t cap,
                                     const char *base, const char *suffix) {
    if (!out || !base || !suffix) return false;
    /* Copy rather than snprintf: the lengths are already known here, so the
     * bound is exact and there is no truncating path for a reader -- or for
     * -Wformat-truncation -- to have to reason about. */
    size_t base_len = strlen(base);
    size_t suffix_len = strlen(suffix);
    if (base_len + suffix_len + 1u > cap) return false;
    memcpy(out, base, base_len);
    memcpy(out + base_len, suffix, suffix_len);
    out[base_len + suffix_len] = '\0';
    return true;
}

/*
 * Copy the live work image out through the block adapter that already owns it.
 *
 * The first version of this opened the image a second time with fopen() and
 * failed closed on Windows, because the adapter holds the only handle the host
 * will grant. Reading through the adapter is also simply more correct: it is
 * the same path the guest's own I/O takes, so a checkpoint cannot disagree with
 * what the guest last wrote.
 */
static bool external_md_copy_media_create_only(const vm_block_t *block,
                                               uint64_t media_size,
                                               const char *dst,
                                               uint64_t *bytes_out) {
    if (bytes_out) *bytes_out = 0;
    if (!block || !block->read_at || !dst) return false;
    FILE *probe = fopen(dst, "rb");
    if (probe) {
        fclose(probe);
        fprintf(stderr, "external-md sidecar: refusing existing %s\n", dst);
        return false;
    }
    FILE *out = fopen(dst, "wb");
    if (!out) {
        fprintf(stderr, "external-md sidecar: cannot create %s\n", dst);
        return false;
    }
    static uint8_t buffer[1u << 20];
    uint64_t done = 0;
    bool ok = true;
    while (done < media_size) {
        uint64_t left = media_size - done;
        size_t want = left < sizeof buffer ? (size_t)left : sizeof buffer;
        size_t got = 0;
        if (block->read_at(block->context, done, buffer, want, &got) !=
                VM_BLOCK_IO_OK || got != want) {
            fprintf(stderr,
                    "external-md sidecar: media read failed at %" PRIu64 "\n",
                    done);
            ok = false;
            break;
        }
        if (fwrite(buffer, 1, got, out) != got) { ok = false; break; }
        done += got;
    }
    if (fflush(out) != 0) ok = false;
    if (fclose(out) != 0) ok = false;
    if (!ok) {
        remove(dst);
        return false;
    }
    if (bytes_out) *bytes_out = done;
    return true;
}

/* Byte-exact copy that refuses an existing destination, preserving the same
 * create-only freshness rule the work-image provisioner enforces. Used on the
 * restore path, where nothing holds the sidecar open. */
static bool external_md_copy_create_only(const char *src, const char *dst,
                                         uint64_t *bytes_out) {
    if (bytes_out) *bytes_out = 0;
    if (!src || !dst) return false;
    FILE *in = fopen(src, "rb");
    if (!in) {
        fprintf(stderr, "external-md sidecar: cannot read %s\n", src);
        return false;
    }
    FILE *probe = fopen(dst, "rb");
    if (probe) {
        fclose(probe);
        fclose(in);
        fprintf(stderr, "external-md sidecar: refusing existing %s\n", dst);
        return false;
    }
    FILE *out = fopen(dst, "wb");
    if (!out) {
        fclose(in);
        fprintf(stderr, "external-md sidecar: cannot create %s\n", dst);
        return false;
    }
    static uint8_t buffer[1u << 20];
    uint64_t total = 0;
    bool ok = true;
    for (;;) {
        size_t got = fread(buffer, 1, sizeof buffer, in);
        if (!got) {
            if (ferror(in)) ok = false;
            break;
        }
        if (fwrite(buffer, 1, got, out) != got) { ok = false; break; }
        total += got;
    }
    if (fflush(out) != 0) ok = false;
    if (fclose(out) != 0) ok = false;
    fclose(in);
    if (!ok) {
        fprintf(stderr, "external-md sidecar: copy %s -> %s failed\n", src, dst);
        remove(dst);
        return false;
    }
    if (bytes_out) *bytes_out = total;
    return true;
}

static bool external_md_sidecar_save(const char *snapshot_path) {
    if (!g_external_work_image_path) return true;   /* not external-md */
    if (!snapshot_path || !g_external_raw_bridge || !g_external_strategy_bridge)
        return false;

    for (unsigned i = 0; i < MD_RAW_BRIDGE_MAX_BOUNCE_SLOTS; i++) {
        if (g_external_raw_bridge->pending[i].active) {
            fprintf(stderr,
                    "external-md sidecar: refusing a checkpoint while native "
                    "uiomove continuation %u is still pending\n", i);
            return false;
        }
    }
    if (g_external_adapter_slot && *g_external_adapter_slot) {
        file_block_status_t flushed =
            file_block_flush(*g_external_adapter_slot);
        if (flushed != FILE_BLOCK_STATUS_OK) {
            fprintf(stderr, "external-md sidecar: flush failed: %s\n",
                    file_block_strerror(flushed));
            return false;
        }
    }

    char image_path[1024];
    char state_path[1024];
    if (!external_md_sidecar_path(image_path, sizeof image_path,
                                  snapshot_path, ".mdimage") ||
        !external_md_sidecar_path(state_path, sizeof state_path,
                                  snapshot_path, ".mdstate")) {
        fprintf(stderr, "external-md sidecar: path too long\n");
        return false;
    }

    uint64_t copied = 0;
    if (!g_external_adapter_slot || !*g_external_adapter_slot ||
        !external_md_copy_media_create_only(
            file_block_get(*g_external_adapter_slot),
            g_external_media_size_for_sidecar, image_path, &copied))
        return false;

    static external_md_sidecar_t sidecar;
    memset(&sidecar, 0, sizeof sidecar);
    sidecar.magic = EXTERNAL_MD_SIDECAR_MAGIC;
    sidecar.version = EXTERNAL_MD_SIDECAR_VERSION;
    sidecar.media_size = g_external_media_size_for_sidecar;
    sidecar.image_bytes = copied;
    sidecar.strategy_stats = g_external_strategy_bridge->stats;
    sidecar.raw_stats = g_external_raw_bridge->stats;
    memcpy(sidecar.guard_tail, g_external_raw_bridge->guard_tail,
           sizeof sidecar.guard_tail);

    FILE *state = fopen(state_path, "rb");
    if (state) {
        fclose(state);
        fprintf(stderr, "external-md sidecar: refusing existing %s\n",
                state_path);
        return false;
    }
    state = fopen(state_path, "wb");
    if (!state) {
        fprintf(stderr, "external-md sidecar: cannot create %s\n", state_path);
        return false;
    }
    bool ok = fwrite(&sidecar, sizeof sidecar, 1, state) == 1;
    if (fflush(state) != 0) ok = false;
    if (fclose(state) != 0) ok = false;
    if (!ok) {
        fprintf(stderr, "external-md sidecar: writing %s failed\n", state_path);
        remove(state_path);
        return false;
    }
    printf("snapshot   : external-md sidecars %s (%" PRIu64 " bytes) and %s\n",
           image_path, copied, state_path);
    fflush(stdout);
    return true;
}

static bool external_md_sidecar_load(const char *snapshot_path,
                                     external_md_sidecar_t *out) {
    if (!snapshot_path || !out) return false;
    char state_path[1024];
    if (!external_md_sidecar_path(state_path, sizeof state_path,
                                  snapshot_path, ".mdstate")) {
        fprintf(stderr, "external-md sidecar: path too long\n");
        return false;
    }
    FILE *state = fopen(state_path, "rb");
    if (!state) {
        fprintf(stderr,
                "external-md restore: missing sidecar %s; a snapshot taken in "
                "external-md mode always writes one\n", state_path);
        return false;
    }
    bool ok = fread(out, sizeof *out, 1, state) == 1;
    fclose(state);
    if (!ok) {
        fprintf(stderr, "external-md restore: short read on %s\n", state_path);
        return false;
    }
    if (out->magic != EXTERNAL_MD_SIDECAR_MAGIC ||
        out->version != EXTERNAL_MD_SIDECAR_VERSION) {
        fprintf(stderr,
                "external-md restore: %s is magic %08x version %u; expected "
                "%08x version %u\n", state_path, out->magic, out->version,
                EXTERNAL_MD_SIDECAR_MAGIC, EXTERNAL_MD_SIDECAR_VERSION);
        return false;
    }
    return true;
}

/* Save every checkpoint due at the machine's current absolute retired-
 * instruction count.  Keeping completion state prevents a checkpoint at the
 * restored starting count from being written again if a failed arm_step()
 * retires no instruction. */
static bool save_due_snapshots(s5l8900_t *mach,
                               boot_snapshot_request_t *snaps,
                               unsigned nsnaps) {
    if (!mach || (!snaps && nsnaps)) return false;
    for (unsigned s = 0; s < nsnaps; s++) {
        if (snaps[s].done || snaps[s].at != mach->cpu.cycles) continue;
        if (!external_md_sidecar_save(snaps[s].path)) {
            fprintf(stderr, "snapshot %s: external-md sidecar failed\n",
                    snaps[s].path);
            return false;
        }
        snapshot_status_t status = snapshot_save(mach, snaps[s].path);
        printf("snapshot   : @%" PRIu64 " -> %s: %s\n",
               mach->cpu.cycles, snaps[s].path, snapshot_strerror(status));
        fflush(stdout);
        if (status != SNAP_OK) {
            fprintf(stderr, "snapshot %s: %s\n",
                    snaps[s].path, snapshot_strerror(status));
            return false;
        }
        snaps[s].done = true;
    }
    return true;
}

/* ceil(part * total / 40), without overflowing when total is near
 * UINT64_MAX. These are the exact half-open boundaries produced by
 * floor(instruction * 40 / total); part is always in [0,40]. */
static uint64_t instruction_bucket_boundary(uint64_t total, unsigned part) {
    return (total / 40u) * part +
           ((total % 40u) * part + 39u) / 40u;
}

/* floor(at * 40 / limit), clamped to the 40-element histogram, again without
 * performing the potentially overflowing multiplication. */
static unsigned instruction_bucket(uint64_t at, uint64_t limit) {
    if (!limit || at >= limit) return at ? 39u : 0u;
    /* Keep the hot-MMIO probe's overwhelmingly common path as cheap as the
     * old expression.  Only astronomical counters need the overflow-safe
     * threshold search. */
    if (at <= UINT64_MAX / 40u)
        return (unsigned)((at * 40u) / limit);
    uint64_t q = limit / 40u;
    uint64_t r = limit % 40u;
    for (unsigned bucket = 0; bucket < 39u; bucket++) {
        unsigned part = bucket + 1u;
        uint64_t ceiling = q * part + (r * part + 39u) / 40u;
        if (at < ceiling) return bucket;
    }
    return 39u;
}

static bool boot_range_make(boot_range_t *range, const char *name,
                            uint64_t begin, uint64_t length, bool active) {
    if (!range || !name || !add_u64(begin, length, &range->end)) return false;
    range->name = name;
    range->begin = begin;
    range->active = active;
    return true;
}

static bool boot_ranges_overlap(const boot_range_t *a,
                                const boot_range_t *b) {
    if (!a->active || !b->active || a->begin == a->end || b->begin == b->end)
        return false;
    return a->begin < b->end && b->begin < a->end;
}

static bool boot_layout_validate(const boot_range_t *dram,
                                 const boot_range_t *ranges, size_t count) {
    for (size_t i = 0; i < count; i++) {
        if (!ranges[i].active) continue;
        if (ranges[i].begin < dram->begin || ranges[i].end > dram->end) {
            fprintf(stderr,
                    "layout: %s [0x%llx,0x%llx) is outside DRAM "
                    "[0x%llx,0x%llx)\n",
                    ranges[i].name,
                    (unsigned long long)ranges[i].begin,
                    (unsigned long long)ranges[i].end,
                    (unsigned long long)dram->begin,
                    (unsigned long long)dram->end);
            return false;
        }
        for (size_t j = 0; j < i; j++) {
            if (!boot_ranges_overlap(&ranges[i], &ranges[j])) continue;
            fprintf(stderr,
                    "layout: %s [0x%llx,0x%llx) overlaps %s "
                    "[0x%llx,0x%llx)\n",
                    ranges[i].name,
                    (unsigned long long)ranges[i].begin,
                    (unsigned long long)ranges[i].end,
                    ranges[j].name,
                    (unsigned long long)ranges[j].begin,
                    (unsigned long long)ranges[j].end);
            return false;
        }
    }
    return true;
}

/*
 * Plan the boot-owned framebuffer immediately after the conservative static
 * reserve.  The reserve is 16 KiB aligned because XNU derives its L1 table
 * base from topOfKernelData and an ARMv6 L1 table has that alignment.
 *
 * This helper deliberately does not decide whether the resulting range lies
 * in DRAM or overlaps another input.  boot_layout_validate() owns those checks
 * and their precise diagnostics; keeping range creation separate prevents an
 * overflow from being mistaken for a merely out-of-bounds placement.
 */
static bool boot_framebuffer_plan(uint64_t static_input_end,
                                  uint64_t framebuffer_length,
                                  bool framebuffer_enabled,
                                  uint64_t *planned_static_end,
                                  boot_range_t *framebuffer) {
    uint64_t aligned_end;
    if (!planned_static_end || !framebuffer ||
        !align_u64(static_input_end, BOOT_TOKD_ALIGNMENT, &aligned_end) ||
        !boot_range_make(framebuffer, "framebuffer",
                         framebuffer_enabled ? aligned_end : 0u,
                         framebuffer_enabled ? framebuffer_length : 0u,
                         framebuffer_enabled))
        return false;
    *planned_static_end = aligned_end;
    return true;
}

/*
 * Finalize topOfKernelData from what was actually loaded and every boot-owned
 * range that must remain outside XNU's free-page pool.  The 0x11000-byte floor
 * is the measured early-bootstrap demand above TOKD: a 16 KiB L1 table plus
 * the immediately following bootstrap allocations.  Check it with subtraction
 * only after proving TOKD is inside DRAM, so no end-address addition can wrap.
 */
static bool boot_static_top_finalize(const boot_range_t *dram,
                                     uint64_t actual_static_end,
                                     const boot_range_t *framebuffer,
                                     uint64_t *top_of_kernel_data) {
    if (!dram || !dram->active || !framebuffer || !top_of_kernel_data ||
        actual_static_end < dram->begin || actual_static_end > dram->end)
        return false;

    uint64_t final_static_end = actual_static_end;
    if (framebuffer->active) {
        if (framebuffer->begin < dram->begin || framebuffer->end > dram->end)
            return false;
        if (framebuffer->end > final_static_end)
            final_static_end = framebuffer->end;
    }

    uint64_t aligned_end;
    if (!align_u64(final_static_end, BOOT_TOKD_ALIGNMENT, &aligned_end) ||
        aligned_end > UINT32_MAX || aligned_end > dram->end ||
        dram->end - aligned_end < BOOT_MIN_BOOTSTRAP_HEADROOM)
        return false;
    *top_of_kernel_data = aligned_end;
    return true;
}

/* ---------------------------------------------------------------------------
 * The guest's /private/etc/fstab describes storage this machine does not have.
 *
 * Stock iPhone OS 3.1.3 ships:
 *
 *     /dev/disk0s1 / hfs ro 0 1
 *     /dev/disk0s2 /private/var hfs rw,nosuid,nodev 0 2
 *
 * disk0 on real hardware is published by AppleNANDFTL (raw NAND -> a linear
 * logical space) with IOFlashPartitionScheme on top of it cutting that space
 * into disk0s1/disk0s2. BOTH of those read undocumented Apple on-media
 * structures — IOFlashPartitionScheme logs "magic on partition table ...
 * doesn't match expected value" and "major version on partition table ...
 * does not match driver", i.e. it validates a format nobody outside Apple has
 * a specification for. Per the project rule we do not invent that layout, so
 * this VM has no disk0 at all: the system volume is the RAM disk md0
 * (bsd/dev/memdev.c), attached from the /chosen/memory-map RAMDisk property.
 *
 * (Worth recording for whoever revisits this: the undocumented part is the
 * NAND side, NOT partitioning in general. IOStorageFamily in this kernelcache
 * carries built-in IOGUIDPartitionScheme and IOFDiskPartitionScheme
 * personalities — both provider IOMedia, IOPropertyMatch Whole — so a block
 * device that ever does get published can be cut up with an ordinary,
 * documented GPT or MBR. What is missing is anything that would publish that
 * IOMedia *at boot*: there is no IOUSBMassStorageClass and no SCSI stack here,
 * and the kernel-side DiskImages entry point di_root_image() is called solely
 * by imageboot/netboot, neither of which is compiled into this kernelcache.
 * The DiskImages stack is not dead — /usr/libexec/mobile_image_mounter and
 * /usr/libexec/debug_image_mount both drive IOHDIXController directly — but
 * they are lockdownd services that attach a .dimage on host request, onto
 * /Developer, long after fstab has been consulted. Nothing attaches anything
 * during the launchd bootstrap, which is where /private/var is needed.)
 *
 * That matters because launchd's bootstrap (launchctl.c, launchd-321) treats
 * the boot-volume fsck as FATAL and everything after it as advisory:
 *
 *     statfs("/", &sfs);
 *     if (sfs.f_flags & MNT_RDONLY) {            // xnu always mounts / ro
 *         fwexec(fsck -p) || fwexec(fsck -fy)
 *             || (fputs("fsck failed!"), reboot(RB_HALT));   // <-- fatal
 *         path_check("/etc/fstab") ? fwexec(mount -vat nonfs)
 *                                  : fwexec(mount -uw /);    // <-- advisory
 *     }
 *
 * /sbin/fsck is the BSD wrapper: it reads /etc/fstab and fscks every entry
 * with a nonzero pass number. Pointed at a /dev/disk0s1 that cannot exist it
 * exits nonzero, twice, and launchd halts the machine. That is the whole
 * reason the boot ended in _halt_all_cpus.
 *
 * So the VM rewrites the record to name the device it actually provides. This
 * is a guest CONFIGURATION change — the same edit you would make porting an
 * OS image to different storage — not a guess at an Apple binary format.
 *
 * It is done as a byte-for-byte in-place overwrite of the exact stock string,
 * which must appear EXACTLY ONCE in the image, so no HFS+ catalog surgery is
 * needed and the file's logicalSize is unchanged; the replacement is padded to
 * the same length with an fstab comment line. If the stock bytes are missing
 * or ambiguous we refuse and say so rather than patch something else.
 * ------------------------------------------------------------------------- */
static const char FSTAB_STOCK[] =
    "/dev/disk0s1 / hfs ro 0 1\n"
    "/dev/disk0s2 /private/var hfs rw,nosuid,nodev 0 2\n";

/* Returns the image offset patched, or (size_t)-1 on refusal. */
static size_t rd_rewrite_fstab(uint8_t *rd, size_t rd_n, const char *line) {
    const size_t stock_n = sizeof FSTAB_STOCK - 1;   /* 76 */
    size_t hit = (size_t)-1, hits = 0;

    for (size_t i = 0; i + stock_n <= rd_n; i++) {
        if (rd[i] == '/' && !memcmp(rd + i, FSTAB_STOCK, stock_n)) {
            if (!hits) hit = i;
            hits++;
        }
    }
    if (hits != 1) {
        fprintf(stderr,
                "fstab: stock record found %u times in the RAM disk, expected "
                "exactly 1 — refusing to patch.\n"
                "       Pass --keep-fstab if this image is deliberately not the "
                "stock 3.1.3 rootfs\n"
                "       (a restore ramdisk, say); silently booting on unchecked "
                "assumptions is\n"
                "       how you lose an afternoon to launchd halting the "
                "machine.\n", (unsigned)hits);
        return (size_t)-1;
    }

    size_t line_n = strlen(line);
    if (line_n + 1 > stock_n) {
        fprintf(stderr, "fstab: replacement is %u bytes, only %u fit in the "
                        "record\n", (unsigned)line_n + 1, (unsigned)stock_n);
        return (size_t)-1;
    }

    /* line "\n", then a comment line of exactly the remaining width. getfsent
     * ignores '#' lines, so the padding is inert but still valid fstab. */
    uint8_t *p = rd + hit;
    memcpy(p, line, line_n);
    p[line_n] = '\n';
    size_t pad = stock_n - line_n - 1;
    if (pad) {
        memset(p + line_n + 1, '#', pad - 1);
        p[stock_n - 1] = '\n';
    }
    return hit;
}

/* ---------------------------------------------------------------------------
 * The system volume has ZERO free blocks, and on this machine that is fatal to
 * everything launchd tries to start.
 *
 * MEASURED on firmware/rootfs.img (iPhone1,2 3.1.3 7E18, 018-6482-014.dmg):
 *
 *     signature HX  version 5  blockSize 4096
 *     totalBlocks 105780  (x 4096 == 433274880 == the image, exactly)
 *     freeBlocks  0
 *     allocation file: 16384 bytes, 1 extent at block 1, 4 blocks
 *     bits 0..105779 all set, bits 105780..131071 all clear
 *
 * That is not damage, it is Apple's build process. The system dmg is sized to
 * fit its contents because on hardware "/" is disk0s1 and stays read-only
 * forever; everything writable lives on disk0s2, a separate volume the restore
 * newfs'es. We have no disk0 at all (see the fstab note above), so "/" is the
 * only volume, we mount it rw — and there is not one free block on it. launchd
 * can create nothing: no /private/var/log/asl, no /private/var/db, no
 * lockdown records, no SpringBoard caches.
 *
 * The volume is therefore grown to make room. HFS+ is a documented format
 * (Apple TN1150), the image is not encrypted or compressed, and every one of
 * the four edits below is named in the spec, so this is not a guess at an
 * Apple layout — it is the layout, applied:
 *
 *   1. volumeHeader.totalBlocks  += n           (the volume gets bigger)
 *   2. volumeHeader.freeBlocks    = recount     (from the bitmap, not arithmetic)
 *   3. allocation file: free the block(s) covering the OLD reserved tail, and
 *      allocate the block(s) covering the NEW one
 *   4. write the alternate volume header at totalBlocks*blockSize - 1024
 *
 * Point 3 is the one worth spelling out. TN1150 puts the alternate volume
 * header 1024 bytes before the end of the volume and reserves the final 512
 * bytes; the allocation block(s) containing that tail are marked in-use and
 * belong to no file. (Verified independently: walking the catalog and the
 * extents overflow file over this image accounts for 105778 of the 105780
 * in-use blocks — the two left over are block 0, which holds the boot blocks
 * plus the primary header, and block 105779, which holds the alternate. Nor
 * COULD a file own that block: extents are whole allocation blocks, so a file
 * owning it would own the alternate header's bytes and be scribbled on every
 * time the volume was flushed.) So when the tail moves, the block it used to
 * occupy becomes ordinary free space and the block it moves to becomes
 * reserved.
 *
 * Getting that wrong in either direction is exactly what fsck_hfs exists to
 * catch, and launchd's bootstrap runs fsck_hfs on every boot here — but do not
 * lean on it. `fsck_hfs -p` QUICK-EXITS on a volume carrying
 * kHFSVolumeUnmounted, and forcing the real scan (by clearing that bit) stops
 * the machine on `SMULBB r6, r3, r5` at fsck_hfs+0x12130, which arm_interp.c
 * traps along with the rest of the SMULxy/SMLAxy DSP space. So the checking
 * here has to stand on its own: hfs_validate() runs over the bytes before the
 * edit AND again after it, and refuses rather than warns.
 *
 * The 16 KB allocation file is the ceiling: 16384 * 8 == 131072 bits, i.e.
 * 512 MB at this block size. Growing past that would mean allocating more
 * blocks TO the allocation file and rewriting its fork extents, which is a
 * different and much more invasive operation. We stop at the ceiling and say
 * so. (TN1150 explicitly allows an allocation file larger than the volume
 * needs, requiring only that the surplus bits be zero — which is why the
 * headroom is there in the first place: newfs_hfs rounded 105780 bits up to a
 * whole 4-block clump.)
 *
 * As with the fstab rewrite, only the in-memory copy is touched, and the RAM
 * disk published to the guest is the grown one, so the device the guest sees
 * and the volume on it are the same size — which fsck_hfs checks (it locates
 * the alternate header from the DEVICE size, via DKIOCGETBLOCKCOUNT).
 * ------------------------------------------------------------------------- */
static uint16_t hbe16(const uint8_t *p) { return (uint16_t)((p[0] << 8) | p[1]); }
static uint32_t hbe32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8)  |  (uint32_t)p[3];
}
static uint64_t hbe64(const uint8_t *p) {
    return ((uint64_t)hbe32(p) << 32) | hbe32(p + 4);
}
static void hput32(uint8_t *p, uint32_t v) {
    p[0] = (uint8_t)(v >> 24); p[1] = (uint8_t)(v >> 16);
    p[2] = (uint8_t)(v >> 8);  p[3] = (uint8_t)v;
}

#define HFS_VH_OFF      1024u     /* TN1150: volume header at byte 1024      */
#define HFS_VH_LEN      512u      /* ...and it is 512 bytes long             */
#define HFS_SIG_HFSPLUS 0x482Bu   /* 'H+' */
#define HFS_SIG_HFSX    0x4858u   /* 'HX' */
#define HFS_ATTR_JOURNALED (1u << 13)

typedef struct {
    uint32_t block_size, total_blocks, free_blocks, next_alloc, attributes;
    uint64_t alloc_bytes;             /* allocation file logicalSize          */
    uint32_t alloc_fork_blocks;
    uint32_t ext_start[8], ext_count[8];
    uint32_t nbits;                   /* bits the allocation file can address */
} hfsvol_t;

/* Image offset of byte `off` of the allocation file, or (size_t)-1 if that
 * byte is past the fork's extents. */
static size_t hfs_alloc_off(const hfsvol_t *v, uint64_t off) {
    uint64_t seen = 0;
    for (unsigned i = 0; i < 8; i++) {
        uint64_t span = (uint64_t)v->ext_count[i] * v->block_size;
        if (!span) continue;
        if (off < seen + span)
            return (size_t)((uint64_t)v->ext_start[i] * v->block_size + (off - seen));
        seen += span;
    }
    return (size_t)-1;
}

static int hfs_bit_get(const uint8_t *img, const hfsvol_t *v, uint32_t bit) {
    size_t o = hfs_alloc_off(v, bit >> 3);
    return (img[o] >> (7 - (bit & 7))) & 1;
}
static void hfs_bit_set(uint8_t *img, const hfsvol_t *v, uint32_t bit, int on) {
    size_t o = hfs_alloc_off(v, bit >> 3);
    uint8_t m = (uint8_t)(1u << (7 - (bit & 7)));
    if (on) img[o] |= m; else img[o] &= (uint8_t)~m;
}

/*
 * Parse and FULLY validate the volume. Every field this tool is about to touch
 * or rely on is checked, and anything unexpected is a refusal, not a warning:
 * a half-understood volume that boots is worse than one that does not, because
 * the damage shows up later as an unexplained guest failure.
 *
 * Run before the edit and again after it, so the "after" pass is an
 * independent re-derivation from the bytes rather than a restatement of what
 * the edit intended.
 */
static bool hfs_validate(const uint8_t *img, size_t n, hfsvol_t *v,
                         const char *when) {
#define VBAD(...) do { fprintf(stderr, "rd-grow (%s): ", when); \
                       fprintf(stderr, __VA_ARGS__); return false; } while (0)
    memset(v, 0, sizeof *v);
    if (n < HFS_VH_OFF + HFS_VH_LEN)
        VBAD("image is %llu bytes — too small for a volume header\n",
             (unsigned long long)n);

    const uint8_t *vh = img + HFS_VH_OFF;
    uint16_t sig = hbe16(vh), ver = hbe16(vh + 2);
    if (!((sig == HFS_SIG_HFSPLUS && ver == 4) || (sig == HFS_SIG_HFSX && ver == 5)))
        VBAD("signature '%c%c' version %u is neither HFS+ (H+/4) nor HFSX "
             "(HX/5) — not growing something this tool does not understand\n",
             vh[0] >= 32 && vh[0] < 127 ? vh[0] : '?',
             vh[1] >= 32 && vh[1] < 127 ? vh[1] : '?', ver);

    v->attributes   = hbe32(vh + 4);
    v->block_size   = hbe32(vh + 40);
    v->total_blocks = hbe32(vh + 44);
    v->free_blocks  = hbe32(vh + 48);
    v->next_alloc   = hbe32(vh + 52);
    uint32_t journal_info_block = hbe32(vh + 12);

    if (v->block_size < 512 || v->block_size > (1u << 20) ||
        (v->block_size & (v->block_size - 1)) || (v->block_size % 512))
        VBAD("blockSize %u is not a power-of-two multiple of 512\n", v->block_size);
    if (!v->total_blocks) VBAD("totalBlocks is 0\n");
    if ((uint64_t)v->total_blocks * v->block_size != (uint64_t)n)
        VBAD("totalBlocks %u x blockSize %u = %llu but the image is %llu bytes "
             "— the volume does not fill the image, and this tool only handles "
             "a bare volume with no partition map around it\n",
             v->total_blocks, v->block_size,
             (unsigned long long)v->total_blocks * v->block_size,
             (unsigned long long)n);
    if (v->free_blocks > v->total_blocks)
        VBAD("freeBlocks %u exceeds totalBlocks %u\n", v->free_blocks, v->total_blocks);
    if (v->next_alloc >= v->total_blocks)
        VBAD("nextAllocation %u is outside the volume (%u blocks)\n",
             v->next_alloc, v->total_blocks);
    /* A journalled volume has a transaction log that would also have to be
     * reasoned about; this image is not journalled and we do not pretend to
     * handle one that is. */
    if ((v->attributes & HFS_ATTR_JOURNALED) || journal_info_block)
        VBAD("volume is journalled (attributes 0x%08x, journalInfoBlock %u) — "
             "not supported\n", v->attributes, journal_info_block);

    /* The alternate volume header, 1024 bytes before the end (TN1150). */
    const uint8_t *avh = img + n - HFS_VH_OFF;
    if (memcmp(vh, avh, HFS_VH_LEN))
        VBAD("the alternate volume header at 0x%llx does not match the primary "
             "— refusing to edit a volume whose two headers already disagree\n",
             (unsigned long long)(n - HFS_VH_OFF));

    /* Allocation file fork descriptor, at offset 112 of the volume header. */
    const uint8_t *af = vh + 112;
    v->alloc_bytes      = hbe64(af);
    v->alloc_fork_blocks = hbe32(af + 12);
    uint32_t summed = 0;
    for (unsigned i = 0; i < 8; i++) {
        v->ext_start[i] = hbe32(af + 16 + i * 8);
        v->ext_count[i] = hbe32(af + 20 + i * 8);
        if (!v->ext_count[i]) continue;
        if ((uint64_t)v->ext_start[i] + v->ext_count[i] > v->total_blocks)
            VBAD("allocation file extent %u (%u+%u) runs past the volume\n",
                 i, v->ext_start[i], v->ext_count[i]);
        summed += v->ext_count[i];
    }
    if (summed != v->alloc_fork_blocks)
        VBAD("allocation file has %u blocks but its 8 inline extents cover %u "
             "— it spills into the extents overflow file, which this tool does "
             "not read\n", v->alloc_fork_blocks, summed);
    if (v->alloc_bytes > (uint64_t)v->alloc_fork_blocks * v->block_size)
        VBAD("allocation file logicalSize %llu exceeds its %u allocated blocks\n",
             (unsigned long long)v->alloc_bytes, v->alloc_fork_blocks);
    if (v->alloc_bytes > 0xffffffffull / 8)
        VBAD("allocation file is implausibly large (%llu bytes)\n",
             (unsigned long long)v->alloc_bytes);
    v->nbits = (uint32_t)(v->alloc_bytes * 8);
    if (v->nbits < v->total_blocks)
        VBAD("allocation file addresses %u blocks, volume has %u\n",
             v->nbits, v->total_blocks);

    /* The bitmap must agree with freeBlocks, and every bit past the end of the
     * volume must be zero (TN1150 requires the surplus to be clear). Both are
     * cheap and both are exactly what a bad edit would break. */
    uint32_t used = 0;
    for (uint32_t b = 0; b < v->total_blocks; b++) used += (uint32_t)hfs_bit_get(img, v, b);
    if (used != v->total_blocks - v->free_blocks)
        VBAD("the bitmap marks %u blocks in use but freeBlocks %u says %u\n",
             used, v->free_blocks, v->total_blocks - v->free_blocks);
    for (uint32_t b = v->total_blocks; b < v->nbits; b++)
        if (hfs_bit_get(img, v, b))
            VBAD("bit %u is set but lies past the end of the volume (%u blocks)"
                 " — TN1150 requires the surplus bits to be zero\n",
                 b, v->total_blocks);
    return true;
#undef VBAD
}

/* First and last allocation block covering the volume's reserved tail: the
 * alternate volume header (last 1024 bytes) and the reserved 512 after it. */
static uint32_t hfs_tail_first(uint32_t total_blocks, uint32_t block_size) {
    return (uint32_t)(((uint64_t)total_blocks * block_size - HFS_VH_OFF) / block_size);
}

/*
 * Grow the volume in a preallocated span by `want_mb` megabytes of FREE space.
 * The caller supplies capacity, so this never reallocates the hundreds-of-MiB
 * image or creates a second full-size host copy. On success rd_np is updated to
 * the exposed length. Returns false, with an explanation, on any refusal — the
 * caller aborts the boot rather than booting an image it did not understand.
 */
static bool rd_grow_volume(uint8_t *img, size_t *rd_np, size_t capacity,
                           uint32_t want_mb) {
    if (!img || !rd_np || *rd_np > capacity) {
        fprintf(stderr, "rd-grow: invalid destination span\n");
        return false;
    }
    size_t n = *rd_np;
    hfsvol_t v;

    if (!hfs_validate(img, n, &v, "before")) return false;

    uint32_t bs = v.block_size;
    uint64_t want_blocks = ((uint64_t)want_mb << 20) / bs;
    /* The tail block we hand back when the reserved region moves is one free
     * block we get for nothing, so ask for one fewer. */
    if (want_blocks) want_blocks--;

    uint64_t want_total = (uint64_t)v.total_blocks + want_blocks;
    uint32_t new_total  = want_total > v.nbits ? v.nbits : (uint32_t)want_total;
    if (new_total <= v.total_blocks) {
        fprintf(stderr, "rd-grow: %u MB is less than one allocation block "
                        "(%u bytes) of growth\n", want_mb, bs);
        return false;
    }
    if (want_total > v.nbits)
        printf("rd-grow    : clamped to the allocation file's %u-bit ceiling "
               "(%llu MB volume);\n"
               "             growing past it means enlarging the allocation "
               "file itself.\n",
               v.nbits, (unsigned long long)((uint64_t)v.nbits * bs) >> 20);

    uint32_t old_tail = hfs_tail_first(v.total_blocks, bs);
    uint32_t new_tail = hfs_tail_first(new_total, bs);

    /* The old reserved tail must be exactly as TN1150 describes it before we
     * hand those blocks back. If it is not, something else owns them and
     * freeing them would corrupt a file. */
    for (uint32_t b = old_tail; b < v.total_blocks; b++)
        if (!hfs_bit_get(img, &v, b)) {
            fprintf(stderr, "rd-grow: block %u holds the alternate volume "
                    "header but is marked FREE — refusing to touch this "
                    "volume\n", b);
            return false;
        }
    for (uint32_t b = new_tail; b < new_total; b++)
        if (b >= v.total_blocks && hfs_bit_get(img, &v, b)) {
            fprintf(stderr, "rd-grow: block %u is past the volume yet already "
                    "allocated\n", b);
            return false;
        }

    uint64_t new_n64 = (uint64_t)new_total * bs;
    if (new_n64 > SIZE_MAX || new_n64 > capacity) {
        fprintf(stderr,
                "rd-grow: %llu-byte result exceeds the %llu-byte destination "
                "capacity\n",
                (unsigned long long)new_n64,
                (unsigned long long)capacity);
        return false;
    }
    size_t new_n = (size_t)new_n64;
    memset(img + n, 0, new_n - n);

    /* (3) the reserved tail moves. */
    for (uint32_t b = old_tail; b < v.total_blocks; b++) hfs_bit_set(img, &v, b, 0);
    for (uint32_t b = new_tail; b < new_total;      b++) hfs_bit_set(img, &v, b, 1);

    /* (2) freeBlocks is RECOUNTED from the bitmap, never computed from the
     * growth, so the header cannot end up describing a bitmap we did not
     * actually write. */
    uint32_t used = 0;
    for (uint32_t b = 0; b < new_total; b++) used += (uint32_t)hfs_bit_get(img, &v, b);

    uint8_t *vh = img + HFS_VH_OFF;
    hput32(vh + 44, new_total);              /* (1) totalBlocks               */
    hput32(vh + 48, new_total - used);       /* (2) freeBlocks                */
    hput32(vh + 52, old_tail);               /* nextAllocation: first free    */

    /* (4) the alternate header, 1024 bytes before the new end. */
    memcpy(img + new_n - HFS_VH_OFF, vh, HFS_VH_LEN);

    *rd_np = new_n;

    hfsvol_t after;
    if (!hfs_validate(img, new_n, &after, "after")) return false;
    if (after.total_blocks != new_total || after.free_blocks != new_total - used) {
        fprintf(stderr, "rd-grow (after): header re-read as %u/%u blocks, "
                "expected %u/%u\n", after.total_blocks, after.free_blocks,
                new_total, new_total - used);
        return false;
    }

    printf("rd-grow    : volume %u -> %u blocks of %u  (%llu -> %llu MB), "
           "free %u -> %u blocks (%llu MB)\n"
             /* NOT "fsck_hfs will check this": it quick-exits on a volume
              * carrying kHFSVolumeUnmounted, and forcing the full scan stops
              * the machine on an unimplemented SMULBB inside fsck_hfs. The
              * guarantee here is hfs_validate() before and after, plus the
              * kernel's own mount. See docs/BOOTLOG.md. */
           "             alternate volume header rewritten at image+0x%llx; "
           "revalidated from the bytes after writing.\n",
           v.total_blocks, new_total, bs,
           (unsigned long long)((uint64_t)v.total_blocks * bs) >> 20,
           (unsigned long long)((uint64_t)new_total * bs) >> 20,
           v.free_blocks, new_total - used,
           (unsigned long long)((uint64_t)(new_total - used) * bs) >> 20,
           (unsigned long long)(new_n - HFS_VH_OFF));
    return true;
}

/* ---------------------------------------------------------------------------
 * Address naming.
 *
 * Both sources — the kernel's own LC_SYMTAB and the prelinked kext load map in
 * __PRELINK_INFO — live in core/src/firmware/ksyms.c so that machoinfo can
 * print the same map without booting anything. Everything here is the thin
 * layer above it: a rotating buffer so several names can appear in one printf,
 * plus context-aware physical/virtual normalization. A raw low PC is never
 * normalized without the observed MMU state because the DRAM aperture overlaps
 * ordinary userspace.
 *
 * The point of the kext half: a hot PC at 0xc0778123 used to be reported as an
 * unsymbolized address and cost a whole diagnosis cycle to attribute. It is
 * now "com.apple.driver.AppleMBX+0x122" the first time it is printed.
 * ------------------------------------------------------------------------- */
#define DTNAME 32                 /* device-tree property names are char[32] */

static ksyms_t  KS;
static uint32_t g_virt_base, g_phys_base, g_ram_size;

typedef enum {
    DIAGNOSTIC_PC_KERNEL,
    DIAGNOSTIC_PC_USER,
    DIAGNOSTIC_PC_UNPROVEN
} diagnostic_pc_space_t;

static uint16_t ld16(const uint8_t *p) {
    return (uint16_t)p[0] | ((uint16_t)p[1] << 8);
}

static uint32_t ld32(const uint8_t *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

/* Resolve an address already proven to be in kernel virtual form. */
static const char *ksym_at(uint32_t addr) {
    static char buf[4][192];
    static unsigned turn;
    char *out = buf[turn++ & 3];
    return ksyms_resolve(&KS, addr, out, sizeof buf[0]);
}

/*
 * Classify an observed PC before symbolizing it.  The numerical DRAM aperture
 * overlaps ordinary 32-bit userspace, so a low PC is a kernel physical alias
 * only while the MMU is off.  User mode wins even in that state: diagnostics
 * must fail closed rather than manufacture kernel/kext evidence.
 */
static diagnostic_pc_space_t diagnostic_pc_observe(
        uint32_t pc, uint32_t cpsr, bool mmu_enabled,
        uint32_t *reported_pc) {
    uint32_t address = pc & ~1u;
    if ((cpsr & ARM_CPSR_MODE_MASK) == ARM_MODE_USR) {
        if (reported_pc) *reported_pc = address;
        return DIAGNOSTIC_PC_USER;
    }
    uint64_t dram_end = (uint64_t)g_phys_base + g_ram_size;
    if (!mmu_enabled && g_virt_base && g_ram_size &&
        address >= g_phys_base && (uint64_t)address < dram_end) {
        uint64_t candidate = (uint64_t)g_virt_base +
                             (address - g_phys_base);
        if (candidate <= UINT32_MAX) {
            address = (uint32_t)candidate;
            if (reported_pc) *reported_pc = address;
            return DIAGNOSTIC_PC_KERNEL;
        }
    }
    if (reported_pc) *reported_pc = address;
    return mmu_enabled && g_virt_base && address >= g_virt_base
        ? DIAGNOSTIC_PC_KERNEL : DIAGNOSTIC_PC_UNPROVEN;
}

static const char *diagnostic_pc_name(diagnostic_pc_space_t space,
                                      uint32_t reported_pc) {
    switch (space) {
        case DIAGNOSTIC_PC_KERNEL:
            return ksym_at(reported_pc);
        case DIAGNOSTIC_PC_USER:
            return "[userspace]";
        case DIAGNOSTIC_PC_UNPROVEN:
            return "[address not proven as kernel]";
        default:
            return "[invalid diagnostic PC class]";
    }
}

static const char *diagnostic_pc_context_name(
        uint32_t pc, uint32_t cpsr, bool mmu_enabled,
        uint32_t *reported_pc) {
    uint32_t normalized = pc & ~1u;
    diagnostic_pc_space_t space = diagnostic_pc_observe(
        pc, cpsr, mmu_enabled, &normalized);
    if (reported_pc) *reported_pc = normalized;
    return diagnostic_pc_name(space, normalized);
}

static bool diagnostic_pc_classifier_selfcheck(void) {
    uint32_t saved_virt_base = g_virt_base;
    uint32_t saved_phys_base = g_phys_base;
    uint32_t saved_ram_size = g_ram_size;
    uint32_t observed = 0;
    bool ok = true;

    /* Fixed non-overlapping geometry keeps this truth table independent of
     * the probeable -P/-V mapping selected by the caller. */
    g_virt_base = UINT32_C(0xc0000000);
    g_phys_base = UINT32_C(0x08000000);
    g_ram_size = UINT32_C(0x08000000);

    ok = ok && diagnostic_pc_observe(
            UINT32_C(0x2fe20e3c), ARM_MODE_USR, true, &observed) ==
            DIAGNOSTIC_PC_USER &&
         observed == UINT32_C(0x2fe20e3c);
    ok = ok && diagnostic_pc_observe(
            UINT32_C(0x08069040), ARM_MODE_SVC, false, &observed) ==
            DIAGNOSTIC_PC_KERNEL &&
         observed == UINT32_C(0xc0069040);
    ok = ok && diagnostic_pc_observe(
            UINT32_C(0x08069040), ARM_MODE_SVC, true, &observed) ==
            DIAGNOSTIC_PC_UNPROVEN &&
         observed == UINT32_C(0x08069040);
    ok = ok && diagnostic_pc_observe(
            UINT32_C(0xc0069040), ARM_MODE_USR, true, &observed) ==
            DIAGNOSTIC_PC_USER &&
         observed == UINT32_C(0xc0069040);
    ok = ok && diagnostic_pc_observe(
            UINT32_C(0xc0069040), ARM_MODE_SVC, true, &observed) ==
            DIAGNOSTIC_PC_KERNEL &&
         observed == UINT32_C(0xc0069040);
    ok = ok && diagnostic_pc_observe(
            UINT32_C(0xc0069040), ARM_MODE_SVC, false, &observed) ==
            DIAGNOSTIC_PC_UNPROVEN &&
         observed == UINT32_C(0xc0069040);

    g_virt_base = UINT32_C(0xfffff800);
    g_phys_base = UINT32_C(0x00001000);
    g_ram_size = UINT32_C(0x00001000);
    diagnostic_pc_space_t overflow_space = diagnostic_pc_observe(
        UINT32_C(0x00001800), ARM_MODE_SVC, false, &observed);
    ok = ok && overflow_space == DIAGNOSTIC_PC_UNPROVEN &&
         observed == UINT32_C(0x00001800);

    g_virt_base = saved_virt_base;
    g_phys_base = saved_phys_base;
    g_ram_size = saved_ram_size;
    return ok;
}

static uint32_t ksym_value(const char *name) { return ksyms_value(&KS, name); }

static uint32_t ksym_next_value(uint32_t value) {
    for (unsigned i = 0; i < KS.nsym; i++)
        if (KS.sym[i].value > value) return KS.sym[i].value;
    return 0;
}

/* The load map, printed by -L and by machoinfo -k. */
static void dump_kext_map(void) {
    printf("=== PRELINKED KEXT LOAD MAP (__PRELINK_TEXT 0x%08x..0x%08x) ===\n",
           KS.prelink_lo, KS.prelink_hi);
    printf("    %-44s %-10s %-10s %-9s %s\n",
           "bundle identifier", "load addr", "end", "size", "kmod_info");
    for (unsigned i = 0; i < KS.nkext; i++) {
        const kext_t *k = &KS.kext[i];
        if (!k->has_exec) continue;
        printf("    %-44s 0x%08x 0x%08x %-9u 0x%08x\n",
               k->bundle, k->addr, k->addr + k->size, k->size, k->kmod_info);
    }
    printf("    --- no executable (KPI pseudo-extensions, never a hot PC) ---\n");
    for (unsigned i = 0; i < KS.nkext; i++)
        if (!KS.kext[i].has_exec) printf("    %s\n", KS.kext[i].bundle);
}

/*
 * Say out loud what we can and cannot name. A profile that reports a bare
 * address is the failure mode this whole module exists to remove, so if the
 * kext map did not parse, the boot log has to shout about it rather than
 * quietly go back to printing hex.
 */
static void report_symbol_sources(void) {
    printf("symbols    : %u kernel symbols (%s)\n",
           KS.nsym, ksyms_strerror(KS.sym_status));
    if (KS.prelink_status == KSYMS_OK) {
        printf("kexts      : %u prelinked, %u with code, 0x%08x..0x%08x\n",
               KS.nkext, KS.nkext_exec, KS.prelink_lo, KS.prelink_hi);
        if (KS.detail[0]) printf("  ! %s\n", KS.detail);
    } else {
        printf("\n"
               "  ############################################################\n"
               "  # KEXT LOAD MAP UNAVAILABLE — hot PCs inside a prelinked   #\n"
               "  # driver will print as bare addresses again.               #\n"
               "  #   %s\n"
               "  #   %s\n"
               "  ############################################################\n\n",
               ksyms_strerror(KS.prelink_status),
               KS.detail[0] ? KS.detail : "(no further detail)");
    }
}

/* ===========================================================================
 * Device-tree patching — standing in for iBoot.
 *
 * The flat-tree walkers and the same-length in-place writers (dtn_path,
 * dt_set_u32, dt_node_compatible_exact, dt_set_reg) moved verbatim into
 * tools/dt_inplace.h, included above, so core/tests/test_devicetree.c can
 * exercise the shipping implementation instead of a copy of it. What stays
 * here is the patching that is specific to this machine's boot.
 * ------------------------------------------------------------------------- */

/*
 * Break a node's "compatible" so no driver matches it. IOKit matches AppleMBX
 * (and friends) purely by IONameMatch against this string; flipping the first
 * byte leaves the length unchanged (so the flat tree is not disturbed) and
 * makes the name match nothing. Used to keep the MBX/PowerVR graphics driver
 * from starting: it busy-polls a wrapper-reset bit in its 16 MB register block
 * that we do not model, which wedges the whole boot at ~72% of runtime. iPhone
 * OS 3 has a software-blit path (LK_ENABLE_MBX2D=0), so the GPU is not required
 * to reach a rendered SpringBoard.
 */
static bool dt_unmatch(uint8_t *b, size_t len, const char *path) {
    size_t node = dtn_path(b, len, path);
    if (node == DT_NONE) { printf("  dt: node /%s NOT FOUND\n", path); return false; }
    uint32_t vl = 0;
    uint8_t *p = dtn_prop(b, len, node, "compatible", &vl);
    if (!p || !vl) { printf("  dt: /%s:compatible missing\n", path); return false; }
    char was = (char)p[0];
    p[0] = 'x';                      /* 'm'bx... -> 'x'bx..., matches nothing */
    printf("  dt: /%-14s compatible '%c...' -> 'x...' (unmatched)\n", path, was);
    return true;
}

/* ---------------------------------------------------------------------------
 * Adding an entry to /chosen/memory-map WITHOUT rebuilding the blob.
 *
 * The obvious problem: this flat format has no relocation table, every offset
 * is implicit in the byte stream, so appending a property to a node in the
 * middle of the tree means rewriting everything after it. That is why every
 * other patch here is same-length and in place.
 *
 * It turns out no rebuild is needed. The shipped tree already carries sixteen
 * placeholders in that node — MemoryMapReserved-0 .. MemoryMapReserved-15 —
 * each with a value of exactly 8 zero bytes, which is exactly the shape of a
 * memory-map entry ({address, size}). That is not a coincidence: it is how
 * iBoot adds entries at run time. It finds a spare placeholder, overwrites the
 * 32-byte name field with the real key, and fills in the two words. Name and
 * value lengths are both unchanged, so the patch is same-length and in place.
 *
 * The one live entry in the shipped tree corroborates the format:
 *   .DeviceTree = {0x00000000, 0x00009e60}   and 0x9e60 == 40544 == the exact
 * size of devicetree.bin. Address zero because iBoot had not run yet.
 *
 * So we do what iBoot does. `claim` is CONFIRMED behaviour of the format, not
 * a trick: renaming a reserved slot is the mechanism the slots exist for.
 * ------------------------------------------------------------------------- */
static bool dt_memmap_add(uint8_t *b, size_t len, const char *key,
                          uint32_t addr, uint32_t size) {
    size_t node = dtn_path(b, len, "chosen/memory-map");
    if (node == DT_NONE) {
        printf("  dt: /chosen/memory-map NOT FOUND — cannot add %s\n", key);
        return false;
    }
    uint32_t np, nc;
    size_t p = dtn_hdr(b, len, node, &np, &nc);
    if (!p) return false;

    size_t slot = 0;                       /* offset of the property record */
    for (uint32_t i = 0; i < np; i++) {
        if (p > len || len - p < 36u) return false;
        char nm[DTNAME + 1];
        memcpy(nm, b + p, DTNAME); nm[DTNAME] = '\0';
        uint32_t l = ld32(b + p + 32) & 0x7fffffffu;
        size_t padded = ((size_t)l + 3u) & ~(size_t)3u;
        if (padded > len - p - 36u) return false;
        /* An existing entry with this key wins: re-running must be idempotent
         * rather than burning a second placeholder each time. */
        if (!strcmp(nm, key) && l == 8) { slot = p; break; }
        if (!slot && l == 8 && !strncmp(nm, "MemoryMapReserved-", 18) &&
            ld32(b + p + 36) == 0 && ld32(b + p + 40) == 0)
            slot = p;                      /* first free placeholder; keep looking
                                            * in case the real key already exists */
        p += 36u + padded;
    }
    if (!slot) {
        printf("  dt: no free MemoryMapReserved-* placeholder for %s\n", key);
        return false;
    }
    char old[DTNAME + 1];
    memcpy(old, b + slot, DTNAME); old[DTNAME] = '\0';
    memset(b + slot, 0, DTNAME);
    memcpy(b + slot, key, strlen(key) < DTNAME ? strlen(key) : DTNAME - 1);
    uint8_t *v = b + slot + 36;
    uint32_t vals[2] = { addr, size };
    for (int i = 0; i < 2; i++) {
        v[i*4+0] = (uint8_t)vals[i];         v[i*4+1] = (uint8_t)(vals[i] >> 8);
        v[i*4+2] = (uint8_t)(vals[i] >> 16); v[i*4+3] = (uint8_t)(vals[i] >> 24);
    }
    printf("  dt: /chosen/memory-map  %-18s -> %-10s {0x%08x,0x%08x}  (in place)\n",
           old, key, addr, size);
    return true;
}

static bool dt_memmap_matches_once(uint8_t *b, size_t len, const char *key,
                                   uint32_t addr, uint32_t size) {
    size_t node = dtn_path(b, len, "chosen/memory-map");
    uint32_t np, nc;
    if (node == DT_NONE) return false;
    size_t p = dtn_hdr(b, len, node, &np, &nc);
    if (!p) return false;
    (void)nc;

    unsigned matches = 0;
    for (uint32_t i = 0; i < np; i++) {
        if (p > len || len - p < 36u) return false;
        char name[DTNAME + 1];
        memcpy(name, b + p, DTNAME);
        name[DTNAME] = '\0';
        uint32_t value_length = ld32(b + p + 32) & UINT32_C(0x7fffffff);
        size_t padded = ((size_t)value_length + 3u) & ~(size_t)3u;
        if (padded > len - p - 36u) return false;
        if (!strcmp(name, key)) {
            if (value_length != 8u || ++matches != 1u ||
                ld32(b + p + 36) != addr ||
                ld32(b + p + 40) != size)
                return false;
        }
        p += 36u + padded;
    }
    return matches == 1u;
}

/*
 * S5L8900 clock rates.
 *
 * RESEARCHED (two independent sources agree):
 *   TB_HZ  6 MHz  — openiBoot plat-s5l8900/clock.c computes
 *                   TimebaseFrequency = FREQUENCY_BASE / 2 with
 *                   FREQUENCY_BASE == 12000000, and measurements of
 *                   mach_absolute_time() on the original iPhone and the
 *                   iPhone 3G report a 6 MHz tick (the 3GS and later are
 *                   24 MHz / the familiar 125:3 timebase). This is the value
 *                   the rtclock panic is actually about.
 *   FIX_HZ 24 MHz — same file: FixedFrequency = FREQUENCY_BASE * 2.
 *   CPU_HZ 412 MHz— the universally documented iPhone 3G core clock
 *                   (ARM1176JZF-S underclocked from ~620 MHz).
 *
 * PROVISIONAL / DERIVED — I could not find a dump of a real iBoot-populated
 * iPhone1,2 tree, and openiBoot reads these out of the PLL registers at run
 * time rather than hard-coding them. These are the self-consistent ratios that
 * fall out of the S5L8900 clock tree (AHB = core/4, peripheral = AHB/2), and
 * nothing the kernel does with them is sensitive to the exact value — only to
 * their being non-zero and to (2*CPU)/BUS being a sane small integer:
 *   BUS_HZ 103 MHz = CPU/4        (bus_to_cpu_rate comes out 8/2 == 4)
 *   MEM_HZ 103 MHz                (LPDDR clock; assumed equal to the bus)
 *   PRF_HZ 51.5 MHz = BUS/2
 * If a real iPhone1,2 IORegistry dump ever turns up, replace these three.
 */
#define S5L8900_CPU_HZ  412000000u
#define S5L8900_BUS_HZ  103000000u
#define S5L8900_MEM_HZ  103000000u
#define S5L8900_PRF_HZ   51500000u
#define S5L8900_FIX_HZ   24000000u
#define S5L8900_TB_HZ     6000000u

/* iBoot reads the three Syrah panel-identification bytes as a big-endian
 * 24-bit value (openiBoot, plat-s5l8900/lcd.c:syrah_init). Its N82/iPhone 3G
 * hardware log records a5:c2:2b. In this repo's shipped AppleMerlotLCD binary,
 * 0xc0651f60 rejects ID zero and 0x8000 and 0xc0651770 branches on the ID's low
 * three bits. The zero in the IPSW tree is therefore only a placeholder. */
#define N82_LCD_PANEL_ID 0x00a5c22bu

/*
 * The panel geometry and the /vram pool below are the CORE's constants, not
 * copies of them, because this harness and core/src/boot/bringup.c publish the
 * same two device-tree properties to the same guest kernel: bringup.c:869 sets
 * /vram:reg from S5L_BRINGUP_VRAM_BYTES, and line 25250 here sets it from
 * N82_VRAM_BYTES. Held apart they described one machine in two places with
 * nothing making them agree.
 *
 * They did disagree, on 2026-07-28. run117, run118 and run126 were three
 * attempts to measure a larger pool that each edited S5L_BRINGUP_VRAM_SURFACES
 * and then ran THIS harness, so all three published the old two-surface value
 * and answered a question nobody asked. One conclusion had to be withdrawn.
 * Aliasing costs nothing and makes that particular morning unrepeatable.
 */
#define N82_FB_WIDTH     S5L_BRINGUP_FB_WIDTH
#define N82_FB_HEIGHT    S5L_BRINGUP_FB_HEIGHT
#define N82_FB_BPP       S5L_BRINGUP_FB_BPP
#define N82_FB_BYTES     S5L_BRINGUP_FB_BYTES

/* ------------------------------------------------ changed-frame meter ----
 *
 * The iOS app's status line measures changed PUBLISHED frames. It does not
 * count CABackingStoreUpdate (one call per layer), CLCD register writes (this
 * guest continuously scans a surface), or the H1 interrupt handler (a display
 * boundary, not proof that any pixel changed). The desktop harness used to
 * expose all three tempting proxies and none of the quantity the app reports.
 *
 * This opt-in meter deliberately transcribes VMEngine.m's publication path:
 *
 *   - execution is checked after each 100,000-instruction host chunk;
 *   - regular publication is capped at 30 Hz on host wall time, with the same
 *     unconditional terminal publication the app makes at an instruction cap;
 *   - the complete 614,400-byte raw surface is copied, as the app copies it;
 *   - one little-endian word every 397 bytes feeds the same sampled FNV-style
 *     signature; and
 *   - changed signatures are reported over windows of at least 0.5 seconds.
 *
 * It is still NOT target-device FPS. bootkernel has diagnostic overhead the
 * app does not, the host CPU is different, and this does not reproduce UIKit's
 * concurrent CGImage work. The report says that prominently. What it buys is
 * a fast, exit-checked way to reject a supposed FPS improvement when the same
 * changed-publication definition does not improve even on the desktop.
 */
#define FRAME_METER_CHUNK_INSTRUCTIONS UINT64_C(100000)
#define FRAME_METER_PUBLISH_INTERVAL   (1.0 / 30.0)
#define FRAME_METER_WINDOW_SECONDS     0.5

/* Same portable clock selection as insnbench. The MSVC fallback is UTC rather
 * than monotonic, so a backwards step invalidates the measurement instead of
 * quietly producing a flattering rate. The compiled choice is printed. */
#if defined(CLOCK_MONOTONIC)
#  define FRAME_METER_TIMER "clock_gettime(CLOCK_MONOTONIC)"
static double frame_meter_now_seconds(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) return -1.0;
    return (double)ts.tv_sec + (double)ts.tv_nsec * 1e-9;
}
#elif defined(TIME_UTC)
#  define FRAME_METER_TIMER "timespec_get(TIME_UTC; non-monotonic fallback)"
static double frame_meter_now_seconds(void) {
    struct timespec ts;
    if (timespec_get(&ts, TIME_UTC) != TIME_UTC) return -1.0;
    return (double)ts.tv_sec + (double)ts.tv_nsec * 1e-9;
}
#else
#  define FRAME_METER_TIMER "clock() fallback"
static double frame_meter_now_seconds(void) {
    return (double)clock() / (double)CLOCKS_PER_SEC;
}
#endif

typedef struct {
    bool enabled;
    bool failed;
    bool exact_chunk_schedule;
    bool signature_valid;
    bool snapshot_blank;
    uint8_t *snapshot;

    uint64_t start_at;
    uint64_t stop_at;
    uint64_t next_chunk_at;
    double started_sec;
    double stopped_sec;
    double last_publish_sec;
    double window_start_sec;

    uint64_t signature;
    uint64_t publications;
    uint64_t valid_publications;
    uint64_t unavailable_publications;
    uint64_t changed_frames;
    uint64_t window_frames;
    uint64_t completed_windows;
    uint64_t zero_windows;
    uint64_t thirty_fps_windows;
    double last_window_fps;
    double min_window_fps;
    double max_window_fps;
    double sum_window_fps;
    double min_window_seconds;
    double max_window_seconds;
    double sum_window_seconds;

    uint64_t first_changed_at;
    uint64_t last_changed_at;
    uint64_t min_changed_insn_gap;
    uint64_t max_changed_insn_gap;
    uint64_t sum_changed_insn_gap;
    double first_changed_sec;
    double last_changed_sec;
    double min_changed_wall_gap;
    double max_changed_wall_gap;
    double sum_changed_wall_gap;
} frame_meter_t;

static uint64_t frame_meter_signature(const uint8_t *fb, size_t n) {
    uint64_t h = UINT64_C(1469598103934665603);
    for (size_t i = 0; i + 4u <= n; i += 397u) {
        uint32_t w = (uint32_t)fb[i] | ((uint32_t)fb[i + 1u] << 8) |
                     ((uint32_t)fb[i + 2u] << 16) |
                     ((uint32_t)fb[i + 3u] << 24);
        h = (h ^ (uint64_t)w) * UINT64_C(1099511628211);
    }
    return h;
}

static bool frame_meter_signature_selfcheck(void) {
    uint8_t bytes[800];
    for (size_t i = 0; i < sizeof bytes; i++)
        bytes[i] = (uint8_t)(i * 37u + 11u);

    uint64_t original = frame_meter_signature(bytes, sizeof bytes);
    if (original != UINT64_C(0x86ecc86db789e123)) return false;

    /* The error direction is pinned too: an unsampled change can be missed,
     * while a sampled word must change the signature. The meter can undercount
     * a tiny update; it cannot invent one. */
    bytes[5] ^= UINT8_C(1);
    if (frame_meter_signature(bytes, sizeof bytes) != original) return false;
    bytes[397] ^= UINT8_C(1);
    return frame_meter_signature(bytes, sizeof bytes) ==
           UINT64_C(0x86eeac6db78a3466);
}

static const uint8_t *frame_meter_live_display(
        const s5l8900_t *mach, size_t *bytes_out) {
    if (bytes_out) *bytes_out = 0;
    if (!mach || !mach->ram || !s5l_clcd_running(&mach->clcd)) return NULL;

    uint32_t active = s5l_clcd_active_window(&mach->clcd);
    uint32_t fb = 0, width = 0, height = 0, stride = 0, format = 0;
    if (active == CLCD_WIN_NONE ||
        !s5l_clcd_window(&mach->clcd, active, &fb, &width, &height,
                         &stride, &format, NULL) ||
        !CLCD_FMT_IS_32BPP(format) ||
        width != N82_FB_WIDTH || height != N82_FB_HEIGHT ||
        stride < width * N82_FB_BPP || fb < mach->ram_base)
        return NULL;

    uint64_t offset = (uint64_t)fb - mach->ram_base;
    uint64_t bytes = (uint64_t)stride * height;
    if (!bytes || bytes > N82_FB_BYTES ||
        offset > mach->ram_size || bytes > mach->ram_size - offset)
        return NULL;

    if (bytes_out) *bytes_out = (size_t)bytes;
    return mach->ram + (size_t)offset;
}

static bool frame_meter_start(frame_meter_t *meter, uint64_t at,
                              bool exact_chunk_schedule) {
    if (!meter || at > UINT64_MAX - FRAME_METER_CHUNK_INSTRUCTIONS)
        return false;
    memset(meter, 0, sizeof *meter);
    meter->snapshot = calloc(1, N82_FB_BYTES);
    if (!meter->snapshot) return false;

    double now = frame_meter_now_seconds();
    if (now < 0.0) {
        free(meter->snapshot);
        meter->snapshot = NULL;
        return false;
    }
    meter->enabled = true;
    meter->exact_chunk_schedule = exact_chunk_schedule;
    meter->snapshot_blank = true;
    meter->start_at = at;
    meter->stop_at = at;
    meter->next_chunk_at = at + FRAME_METER_CHUNK_INSTRUCTIONS;
    meter->started_sec = now;
    meter->stopped_sec = now;
    meter->last_publish_sec = now;
    return true;
}

static void frame_meter_advance_chunk(frame_meter_t *meter, uint64_t at) {
    if (!meter) return;
    while (meter->next_chunk_at <= at) {
        if (meter->next_chunk_at >
                UINT64_MAX - FRAME_METER_CHUNK_INSTRUCTIONS) {
            meter->next_chunk_at = UINT64_MAX;
            return;
        }
        meter->next_chunk_at += FRAME_METER_CHUNK_INSTRUCTIONS;
    }
}

static void frame_meter_record_window(frame_meter_t *meter, double now) {
    if (!meter) return;
    if (meter->window_start_sec <= 0.0) {
        meter->window_start_sec = now;
        return;
    }
    double elapsed = now - meter->window_start_sec;
    if (elapsed < FRAME_METER_WINDOW_SECONDS) return;

    double fps = (double)meter->window_frames / elapsed;
    if (!meter->completed_windows || fps < meter->min_window_fps)
        meter->min_window_fps = fps;
    if (!meter->completed_windows || fps > meter->max_window_fps)
        meter->max_window_fps = fps;
    if (!meter->completed_windows || elapsed < meter->min_window_seconds)
        meter->min_window_seconds = elapsed;
    if (!meter->completed_windows || elapsed > meter->max_window_seconds)
        meter->max_window_seconds = elapsed;
    meter->completed_windows++;
    if (!meter->window_frames) meter->zero_windows++;
    if (fps >= 30.0) meter->thirty_fps_windows++;
    meter->last_window_fps = fps;
    meter->sum_window_fps += fps;
    meter->sum_window_seconds += elapsed;
    meter->window_frames = 0;
    meter->window_start_sec = now;
}

static bool frame_meter_publish(frame_meter_t *meter, const s5l8900_t *mach,
                                uint64_t at, double now) {
    if (!meter || !meter->enabled || meter->failed) return false;
    if (now < 0.0 || now < meter->last_publish_sec || now < meter->started_sec) {
        meter->failed = true;
        return false;
    }
    meter->last_publish_sec = now;
    meter->publications++;

    size_t fb_bytes = 0;
    const uint8_t *fb = frame_meter_live_display(mach, &fb_bytes);
    if (!fb) {
        meter->unavailable_publications++;
        if (!meter->snapshot_blank) {
            memset(meter->snapshot, 0, N82_FB_BYTES);
            meter->snapshot_blank = true;
        }
        return true;
    }

    meter->valid_publications++;
    if (fb_bytes < N82_FB_BYTES)
        memset(meter->snapshot + fb_bytes, 0, N82_FB_BYTES - fb_bytes);
    memcpy(meter->snapshot, fb, fb_bytes);
    meter->snapshot_blank = false;

    uint64_t signature = frame_meter_signature(fb, fb_bytes);
    if (!meter->signature_valid || signature != meter->signature) {
        if (!meter->changed_frames) {
            meter->first_changed_at = at;
            meter->first_changed_sec = now;
        } else {
            uint64_t insn_gap = at - meter->last_changed_at;
            double wall_gap = now - meter->last_changed_sec;
            if (meter->changed_frames == 1u ||
                insn_gap < meter->min_changed_insn_gap)
                meter->min_changed_insn_gap = insn_gap;
            if (meter->changed_frames == 1u ||
                insn_gap > meter->max_changed_insn_gap)
                meter->max_changed_insn_gap = insn_gap;
            if (meter->changed_frames == 1u ||
                wall_gap < meter->min_changed_wall_gap)
                meter->min_changed_wall_gap = wall_gap;
            if (meter->changed_frames == 1u ||
                wall_gap > meter->max_changed_wall_gap)
                meter->max_changed_wall_gap = wall_gap;
            meter->sum_changed_insn_gap += insn_gap;
            meter->sum_changed_wall_gap += wall_gap;
        }
        meter->signature = signature;
        meter->signature_valid = true;
        meter->changed_frames++;
        meter->window_frames++;
        meter->last_changed_at = at;
        meter->last_changed_sec = now;
    }
    frame_meter_record_window(meter, now);
    return true;
}

static bool frame_meter_poll(frame_meter_t *meter, const s5l8900_t *mach,
                             uint64_t at) {
    if (!meter || !meter->enabled || meter->failed ||
        at < meter->next_chunk_at)
        return meter && !meter->failed;
    frame_meter_advance_chunk(meter, at);

    double now = frame_meter_now_seconds();
    if (now < 0.0 || now < meter->last_publish_sec) {
        meter->failed = true;
        return false;
    }
    if (now - meter->last_publish_sec < FRAME_METER_PUBLISH_INTERVAL)
        return true;
    return frame_meter_publish(meter, mach, at, now);
}

static bool frame_meter_finish(frame_meter_t *meter, const s5l8900_t *mach,
                               uint64_t at) {
    if (!meter || !meter->enabled) return false;
    double now = frame_meter_now_seconds();
    if (!meter->failed &&
        !frame_meter_publish(meter, mach, at, now))
        meter->failed = true;
    if (now >= meter->started_sec) meter->stopped_sec = now;
    meter->stop_at = at;
    return !meter->failed;
}

static void frame_meter_report(const frame_meter_t *meter) {
    if (!meter || !meter->enabled) return;
    double wall = meter->stopped_sec - meter->started_sec;
    printf("\n=== APP-EQUIVALENT CHANGED-SCANOUT METER ===\n");
    printf("  IMPORTANT: this is desktop bootkernel cadence, NOT measured "
           "iOS-device FPS and not a composite count. It mirrors the app's "
           "emulator-thread publication/counter path, not UIKit drawing.\n");
    printf("  validity: %s; timer=%s\n",
           meter->failed ? "INVALID (clock/allocation failure)" : "valid",
           FRAME_METER_TIMER);
    printf("  contract: 100000-instruction schedule (%s), regular <=30 Hz "
           "plus terminal publication, "
           "614400-byte copies, 397-byte sampled-signature stride, >=0.5 s "
           "windows\n",
           meter->exact_chunk_schedule
               ? "exact app-shaped chunk boundaries"
               : "<=1023-instruction diagnostic-loop quantization");
    printf("  span: @%" PRIu64 "..@%" PRIu64 " in %.6f host s",
           meter->start_at, meter->stop_at, wall);
    if (wall > 0.0)
        printf(" = %.3f M guest retired/s",
               (double)(meter->stop_at - meter->start_at) / wall / 1e6);
    printf("\n");
    printf("  publications: %" PRIu64 " total; %" PRIu64
           " live-scanout / %" PRIu64 " unavailable; changed signatures=%"
           PRIu64 " (the first live signature counts, exactly as in the app)\n",
           meter->publications, meter->valid_publications,
           meter->unavailable_publications, meter->changed_frames);
    printf("  signature work: 1548 sampled words / 6192 touched bytes per "
           "live publication; a small unsampled change can be missed, never "
           "invented\n");
    if (meter->completed_windows) {
        printf("  completed windows: %" PRIu64
               "; fps last/min/mean/max=%.3f/%.3f/%.3f/%.3f; "
               "zero/>=30=%" PRIu64 "/%" PRIu64 "\n",
               meter->completed_windows, meter->last_window_fps,
               meter->min_window_fps,
               meter->sum_window_fps / (double)meter->completed_windows,
               meter->max_window_fps, meter->zero_windows,
               meter->thirty_fps_windows);
        printf("  window seconds min/mean/max=%.6f/%.6f/%.6f; "
               "pending changed frames=%" PRIu64 "\n",
               meter->min_window_seconds,
               meter->sum_window_seconds /
                   (double)meter->completed_windows,
               meter->max_window_seconds, meter->window_frames);
    } else {
        printf("  completed windows: 0; no FPS value exists for this run "
               "(pending changed frames=%" PRIu64 ")\n",
               meter->window_frames);
    }
    if (meter->changed_frames) {
        printf("  first/last changed publication: @%" PRIu64 "/@%" PRIu64,
               meter->first_changed_at, meter->last_changed_at);
        if (meter->changed_frames > 1u) {
            double gaps = (double)(meter->changed_frames - 1u);
            printf("\n  changed gaps: instructions min/mean/max=%" PRIu64
                   "/%.1f/%" PRIu64 "; host s min/mean/max="
                   "%.6f/%.6f/%.6f",
                   meter->min_changed_insn_gap,
                   (double)meter->sum_changed_insn_gap / gaps,
                   meter->max_changed_insn_gap,
                   meter->min_changed_wall_gap,
                   meter->sum_changed_wall_gap / gaps,
                   meter->max_changed_wall_gap);
        }
        printf("\n");
    }
}

static void frame_meter_destroy(frame_meter_t *meter) {
    if (!meter) return;
    free(meter->snapshot);
    meter->snapshot = NULL;
}

/*
 * HOW MANY SURFACES /vram MUST HOLD, and why one is not enough.
 *
 * `/vram` is not the scanout buffer. It is the pool IOSurface allocates every
 * surface from, and 691b727 sized it to exactly ONE framebuffer -- which was
 * enough to make the first frame appear and is the reason nothing after it
 * ever did.
 *
 * IOSurfaceDeviceMemoryRegion::init (0xc0527b20) hands the region's length
 * less one to IORangeAllocator::withRange -- the `sub r0, r0, #1` is at
 * 0xc0527c04 and the `blx` at 0xc0527c08. THAT MINUS ONE COSTS NOTHING: the
 * range is inclusive, so withRange(L-1) yields the single element [0, L-1],
 * which is exactly L bytes. IORangeAllocator::init proves it by calling
 * deallocate(0, endOfRange + 1) at 0xc0194824, getFreeCount sums end + 1 -
 * start at 0xc019469c, and the kext asserts getFreeCount() == getLength() for
 * an idle region at 0xc0527a30.
 *
 * The admission test is at 0xc0194bb2: accept iff elem.end >= aligned(start)
 * + round_up(size, 0x1000) - 1. Blocks pack from offset 0 with no slack, so
 *
 *     N(L) = floor(L / 0x96000)
 *
 * exactly. There is no off-by-one, and the free list is not fixed-capacity
 * either: withRange gets capacity 0 (0xc0527bec), init turns that into
 * capacityIncrement 1, and allocElement grows the array through _IOMalloc at
 * 0xc0194700. Fragmentation and exhaustion of the element list are both ruled
 * out. Every pool this harness has ever configured was sized correctly.
 *
 * WHAT ACTUALLY TAKES A BLOCK. AppleH1CLCD does NOT call IOSurface::allocate
 * and structurally cannot emit "buffer allocation failed". At 0xc0705f00 it
 * builds a dictionary carrying only "IOSurfaceIsGlobal" and NO geometry, so
 * init computes size 0, logs "IOSurface: buffer allocation size is zero"
 * (0xc0525090) and the guard at 0xc05260c0 skips allocate entirely -- which is
 * why every run prints that line exactly once. It then sets size = pitch *
 * height = 0x96000 by hand (0xc0706064-0xc0706078), looks up the region by
 * name at 0xc07060a0 and takes a block directly at 0xc07060bc. That allocation
 * is SILENT, and its failure path at 0xc07060c4 falls back to a physical
 * address from its own mode table (0xc0706210). So the display always gets a
 * scanout buffer whether or not the pool had room, which is why run85 and
 * run86 rendered byte-identical frames.
 *
 * The consequence for sizing: one block is consumed before any client sees the
 * pool.
 *
 *     N_client(L) = floor(L / 0x96000) - 1
 *
 * so run85 left userspace ONE surface and run86 left it TWO.
 *
 * IOSurface::allocate's IOBufferMemoryDescriptor branch is gated at 0xc05244e4
 * on getProperty("iommu-present"), and `iommu-present` occurs ZERO times in
 * the shipped device tree -- correctly, because S5L8900 has no DART. Adding it
 * would route allocations to memory the display cannot scan out, which is a
 * worse failure than this one because it would look like it worked. Note the
 * gate is only REACHED when the surface has a non-empty region list; a surface
 * with [+0x90] == 0 goes straight to withOptions at 0xc05244f0, so not every
 * failure line means the pool was exhausted.
 *
 * The observable consequence, measured in run76 and run83: the swap pipeline
 * runs perfectly -- 289 VBLs, 150 swaps committed, every commandWakeup
 * delivered -- and commits the SAME surface at 0x0885c000 every time, because
 * it is the only one that exists. A compositor with one surface can show a
 * boot spinner. It cannot show a home screen over a wallpaper.
 *
 * TWO IS THE MEASURED OPTIMUM. run85 drew the lock screen -- status bar,
 * wallpaper, slide to unlock, 273,206 of 460,800 bytes non-zero against 1,659
 * the run before -- and logged exactly one
 *
 *     IOSurface warning: buffer allocation failed.  320 x 480
 *     fmt: 42475241 size: 614400 bytes
 *
 * where 0x42475241 is 'BGRA'. AppleH1CLCD's layer table has three entries
 * (layer 0 -> window 0, layer 1 -> window 2, layer 2 -> the video overlay), so
 * three looked like the real number, and run86 tried it.
 *
 * THREE IS WORSE. run86 was run85 with this constant at 3 and nothing else
 * changed -- same 6e9 instruction cap, same flags, same clean build:
 *
 *                        run85 (2)         run86 (3)
 *     console total      6,571 bytes       17,821 bytes
 *     alloc failures     1                 122 (12,709 bytes)
 *     genuine output     ~6,480 bytes      5,112 bytes
 *     rendered frame     273,206/460,800   273,206/460,800
 *
 * The frame is byte-identical, the extra console is ENTIRELY the 122 failure
 * lines, and the guest printed about 1.4 KB LESS real output. So the third
 * surface is never successfully handed out. Enlarging the pool only bought
 * some client the chance to ask again and fail, apparently once per composite.
 *
 * That is the useful thing run86 paid for, and static analysis has since
 * closed the question it opened. THE KERNEL HAS NO RETRY. IOSurface::allocate
 * (0xc05242ec) has exactly one reference in the whole kernelcache -- vtable
 * slot +0x70 at 0xc052e048 -- reached from one guarded, non-looping call site
 * at 0xc0526108, and IOSurfaceRoot::createSurface releases the surface and
 * returns NULL on failure with every branch forward. So 122 failure lines are
 * 122 DISTINCT createSurface calls, and the only sites that make them
 * (0xc052a914, 0xc052aae8, 0xc052ac44) take an owning task and a
 * client-supplied dictionary: they are IOSurfaceRootUserClient external
 * methods. The loop is in USERSPACE, one IOConnectCall per line.
 *
 * Why that client asked once with one surface available and 122 times with two
 * is NOT determined, and nothing in this kernel encodes it. So the next
 * increment is still the wrong experiment -- no region length can be read off
 * statically, and a pool sized by trial would hide exactly the kind of leak
 * this constant makes visible. Four probes settle it in one boot, at PCs where
 * the operands are live:
 *
 *   0xc0527ae4  every /vram allocation: r1 = size in, r0 = success out,
 *               including AppleH1CLCD's silent one
 *   0xc0526108  every IOSurface::allocate, i.e. every loud client attempt
 *   0xc05244e4  vs 0xc0524528: pool exhausted or withOptions returned NULL
 *   0xc07060c0  whether AppleH1CLCD got its block or took the fallback
 *
 * Two is kept until those counters say what the client actually wants.
 *
 * PARTLY ANSWERED, 2026-07-28, run127. A different probe than the four above --
 * the region gate at 0xc0524454, read at 0xc0524458 -- reports 1 for both
 * allocations under a four-surface pool and 0 for the second under two. The
 * second request is offset 0x12c000 + length 0x96000 and a two-surface pool
 * ends at exactly 0x12c000, so it starts one whole surface past the end and
 * the gate is simply doing bounds arithmetic. Three is the observed minimum.
 *
 * The paragraph above is therefore too strong: the increment was not the wrong
 * experiment, it was an experiment three earlier runs failed to actually
 * perform (they edited the core constant while this file read its own copy --
 * that is why these are now aliases). What survives from it is the reason two
 * is STILL the shipped value: run127 cleared the refusal and reached the same
 * console milestone, so nothing has yet connected the gate to a drawn pixel,
 * and a pool sized by trial would hide the leak this constant makes visible.
 */
#define N82_VRAM_SURFACES S5L_BRINGUP_VRAM_SURFACES
#define N82_VRAM_BYTES    S5L_BRINGUP_VRAM_BYTES

static uint16_t boot_args_get_le16(const uint8_t *bytes, size_t offset) {
    return (uint16_t)bytes[offset] |
           (uint16_t)((uint16_t)bytes[offset + 1u] << 8);
}

static uint32_t boot_args_get_le32(const uint8_t *bytes, size_t offset) {
    return (uint32_t)bytes[offset] |
           ((uint32_t)bytes[offset + 1u] << 8) |
           ((uint32_t)bytes[offset + 2u] << 16) |
           ((uint32_t)bytes[offset + 3u] << 24);
}

static void boot_args_put_le16(uint8_t *bytes, size_t offset, uint16_t value) {
    bytes[offset] = (uint8_t)value;
    bytes[offset + 1u] = (uint8_t)(value >> 8);
}

static void boot_args_put_le32(uint8_t *bytes, size_t offset, uint32_t value) {
    bytes[offset] = (uint8_t)value;
    bytes[offset + 1u] = (uint8_t)(value >> 8);
    bytes[offset + 2u] = (uint8_t)(value >> 16);
    bytes[offset + 3u] = (uint8_t)(value >> 24);
}

/*
 * Old -F snapshots can contain the pre-fix handoff: Boot_Video points near the
 * top of DRAM while topOfKernelData stops below it.  XNU therefore owns those
 * framebuffer pages as ordinary free memory and can overwrite scanout before
 * IOMobileFramebuffer adopts it.  Recognize only this exact boot_args family;
 * an arbitrary late-boot byte sequence must never be rejected as a snapshot
 * merely because four words happen to resemble addresses.
 */
static bool boot_args_video_layout_unsafe(
        const uint8_t *boot_args, size_t length,
        uint32_t expected_virt_base, uint32_t expected_phys_base,
        uint32_t expected_ram_size, uint32_t *framebuffer_begin_out,
        uint64_t *framebuffer_end_out, uint32_t *top_out) {
    if (!boot_args || length < 0x2cu ||
        boot_args_get_le16(boot_args, 0x02u) != 6u ||
        boot_args_get_le32(boot_args, 0x04u) != expected_virt_base ||
        boot_args_get_le32(boot_args, 0x08u) != expected_phys_base ||
        boot_args_get_le32(boot_args, 0x0cu) != expected_ram_size)
        return false;

    uint32_t top = boot_args_get_le32(boot_args, 0x10u);
    uint32_t framebuffer_begin = boot_args_get_le32(boot_args, 0x14u);
    if (!framebuffer_begin ||
        boot_args_get_le32(boot_args, 0x1cu) !=
            N82_FB_WIDTH * N82_FB_BPP ||
        boot_args_get_le32(boot_args, 0x20u) != N82_FB_WIDTH ||
        boot_args_get_le32(boot_args, 0x24u) != N82_FB_HEIGHT ||
        boot_args_get_le32(boot_args, 0x28u) != N82_FB_BPP * 8u)
        return false;

    uint64_t framebuffer_end;
    uint64_t dram_end;
    if (!add_u64(framebuffer_begin, N82_FB_BYTES, &framebuffer_end) ||
        !add_u64(expected_phys_base, expected_ram_size, &dram_end))
        return false;
    if (framebuffer_begin_out) *framebuffer_begin_out = framebuffer_begin;
    if (framebuffer_end_out) *framebuffer_end_out = framebuffer_end;
    if (top_out) *top_out = top;

    if ((top & (uint32_t)(BOOT_TOKD_ALIGNMENT - 1u)) != 0u ||
        top < expected_phys_base || (uint64_t)top > dram_end)
        return true;
    return dram_end - top < BOOT_MIN_BOOTSTRAP_HEADROOM ||
           framebuffer_begin < expected_phys_base ||
           framebuffer_end > dram_end || framebuffer_end > top;
}

static bool restored_boot_video_layout_unsafe(
        const s5l8900_t *mach, uint32_t boot_args_pa,
        uint32_t expected_virt_base, uint32_t *framebuffer_begin_out,
        uint64_t *framebuffer_end_out, uint32_t *top_out) {
    uint64_t ram_end;
    uint64_t boot_args_end;
    if (!mach || !mach->ram ||
        !add_u64(mach->ram_base, mach->ram_size, &ram_end) ||
        !add_u64(boot_args_pa, 0x2cu, &boot_args_end) ||
        boot_args_pa < mach->ram_base || boot_args_end > ram_end)
        return false;

    size_t offset = (size_t)((uint64_t)boot_args_pa - mach->ram_base);
    return boot_args_video_layout_unsafe(
        mach->ram + offset, (size_t)(ram_end - boot_args_pa),
        expected_virt_base, mach->ram_base, mach->ram_size,
        framebuffer_begin_out, framebuffer_end_out, top_out);
}

/*
 * Firmware-free startup coverage for the placement arithmetic.  In the exact
 * 128 MiB external-md layout, the four raw-I/O slots end at 0x0885c000.  -F
 * must begin there, end at 0x088f2000, and raise the 16 KiB-aligned TOKD to
 * 0x088f4000.  Public CI reaches this before its intentional missing-firmware
 * rejection, so these constants cannot drift behind an Apple-only test.
 */
static bool boot_memory_layout_selfcheck(void) {
    boot_range_t dram;
    boot_range_t framebuffer;
    uint64_t planned_static_end;
    uint64_t top;
    if (!boot_range_make(&dram, "selfcheck DRAM", UINT64_C(0x08000000),
                         UINT64_C(0x08000000), true) ||
        !boot_framebuffer_plan(UINT64_C(0x0885c000), N82_FB_BYTES, true,
                               &planned_static_end, &framebuffer) ||
        planned_static_end != UINT64_C(0x0885c000) ||
        framebuffer.begin != UINT64_C(0x0885c000) ||
        framebuffer.end != UINT64_C(0x088f2000) ||
        !boot_layout_validate(&dram, &framebuffer, 1u) ||
        !boot_static_top_finalize(&dram, UINT64_C(0x0885c000),
                                  &framebuffer, &top) ||
        top != UINT64_C(0x088f4000))
        return false;

    if (!boot_framebuffer_plan(UINT64_C(0x0885c000), N82_FB_BYTES, false,
                               &planned_static_end, &framebuffer) ||
        framebuffer.active ||
        !boot_static_top_finalize(&dram, UINT64_C(0x0885c000),
                                  &framebuffer, &top) ||
        top != UINT64_C(0x0885c000))
        return false;

    if (boot_static_top_finalize(&dram, UINT64_C(0x0fff0000),
                                 &framebuffer, &top) ||
        boot_framebuffer_plan(UINT64_MAX, N82_FB_BYTES, true,
                              &planned_static_end, &framebuffer))
        return false;

    uint8_t boot_args[0x2c] = {0};
    boot_args_put_le16(boot_args, 0x02u, 6u);
    boot_args_put_le32(boot_args, 0x04u, UINT32_C(0xc0000000));
    boot_args_put_le32(boot_args, 0x08u, UINT32_C(0x08000000));
    boot_args_put_le32(boot_args, 0x0cu, UINT32_C(0x08000000));
    boot_args_put_le32(boot_args, 0x10u, UINT32_C(0x0885c000));
    boot_args_put_le32(boot_args, 0x14u, UINT32_C(0x0ff6a000));
    boot_args_put_le32(boot_args, 0x1cu, N82_FB_WIDTH * N82_FB_BPP);
    boot_args_put_le32(boot_args, 0x20u, N82_FB_WIDTH);
    boot_args_put_le32(boot_args, 0x24u, N82_FB_HEIGHT);
    boot_args_put_le32(boot_args, 0x28u, N82_FB_BPP * 8u);
    if (!boot_args_video_layout_unsafe(
            boot_args, sizeof boot_args, UINT32_C(0xc0000000),
            UINT32_C(0x08000000), UINT32_C(0x08000000), NULL, NULL, NULL))
        return false;

    boot_args_put_le32(boot_args, 0x10u, UINT32_C(0x088f4000));
    boot_args_put_le32(boot_args, 0x14u, UINT32_C(0x0885c000));
    return !boot_args_video_layout_unsafe(
        boot_args, sizeof boot_args, UINT32_C(0xc0000000),
        UINT32_C(0x08000000), UINT32_C(0x08000000), NULL, NULL, NULL);
}

/* Applied in order; later entries win, and -D on the command line wins over
 * all of them. Nothing here changes firmware/devicetree.bin on disk — this
 * runs on the copy that is about to be loaded into guest RAM. */
static const struct { const char *path, *prop; uint32_t val; } DT_PATCH[] = {
    /* Root clock-frequency. PROVISIONAL: I have not found anything in
     * xnu-1357 that reads it, and no dump that says what iBoot puts there;
     * the SoC/bus clock is the plausible reading of the name. */
    { "",          "clock-frequency",      S5L8900_BUS_HZ },
    { "cpus/cpu0", "timebase-frequency",   S5L8900_TB_HZ  },
    { "cpus/cpu0", "clock-frequency",      S5L8900_CPU_HZ },
    { "cpus/cpu0", "bus-frequency",        S5L8900_BUS_HZ },
    { "cpus/cpu0", "memory-frequency",     S5L8900_MEM_HZ },
    { "cpus/cpu0", "peripheral-frequency", S5L8900_PRF_HZ },
    { "cpus/cpu0", "fixed-frequency",      S5L8900_FIX_HZ },
};
#define NDTPATCH ((unsigned)(sizeof DT_PATCH / sizeof DT_PATCH[0]))

/* ---------------------------------------------------------------------------
 * Reading guest memory from the host, bypassing the MMU.
 *
 * Every address the kernel hands to panic() lives in the flat kernel window,
 * so the linear virt->phys relation is enough and cannot itself fault.
 * ------------------------------------------------------------------------- */
static s5l8900_t *g_mach;

static const uint8_t *guest_ptr(uint32_t va, uint32_t need) {
    uint32_t pa = va - g_virt_base + g_phys_base;
    if (va < g_virt_base) pa = va;                     /* already physical */
    if (pa < g_mach->ram_base) return NULL;
    uint32_t o = pa - g_mach->ram_base;
    if (o >= g_mach->ram_size || g_mach->ram_size - o < need) return NULL;
    return g_mach->ram + o;
}

/*
 * Find the exact ARM exception-return instruction used by this kernel instead
 * of assuming a transcribed offset.  A raw syscall result is trustworthy only
 * on the SVC->USR transition executed by MOVS pc,lr in
 * _thread_exception_return.  Refuse the probe unless that instruction is
 * unique inside the symbol's exact range.
 */
static uint32_t discover_thread_exception_return_gate(void) {
    const uint32_t movs_pc_lr = UINT32_C(0xe1b0f00e);
    const uint32_t scan_bytes = UINT32_C(0x100);
    uint32_t start = ksym_value("_thread_exception_return") & ~1u;
    uint32_t end = ksym_next_value(start);
    if (!start || start > UINT32_MAX - scan_bytes) {
        printf("SpringBoard return gate: DISABLED"
               " (_thread_exception_return address unresolved)\n");
        return 0;
    }
    uint32_t scan_limit = start + scan_bytes;
    if (!end || end > scan_limit) end = scan_limit;
    if (end <= start || end - start < 4u) {
        printf("SpringBoard return gate: DISABLED"
               " (_thread_exception_return scan range invalid)\n");
        return 0;
    }

    uint32_t found = 0;
    unsigned matches = 0;
    for (uint32_t pc = start; pc <= end - 4u; pc += 4u) {
        const uint8_t *p = guest_ptr(pc, 4u);
        if (!p || ld32(p) != movs_pc_lr) continue;
        found = pc;
        matches++;
    }
    if (matches != 1u) {
        printf("SpringBoard return gate: DISABLED"
               " (expected one MOVS pc,lr in %08x..%08x, found %u)\n",
               start, end, matches);
        return 0;
    }

    printf("SpringBoard return gate: %08x"
           " (unique MOVS pc,lr in _thread_exception_return)\n", found);
    return found;
}

static bool decode_thumb_bl_target(uint32_t pc, uint16_t first,
                                   uint16_t second, uint32_t *target) {
    /* ARMv6 Thumb-1 BL: signed high 11 bits followed by low 11 bits. */
    if ((first & 0xf800u) != 0xf000u ||
        (second & 0xf800u) != 0xf800u || !target) return false;
    uint32_t encoded = ((uint32_t)(first & 0x07ffu) << 12) |
                       ((uint32_t)(second & 0x07ffu) << 1);
    int64_t displacement = (encoded & UINT32_C(0x00400000))
                         ? (int64_t)encoded - INT64_C(0x00800000)
                         : (int64_t)encoded;
    int64_t destination = (int64_t)pc + 4 + displacement;
    if (destination < 0 || destination > UINT32_MAX) return false;
    *target = (uint32_t)destination;
    return true;
}

static bool kernel_thumb_bl_target(uint32_t callsite,
                                   uint32_t *target) {
    const uint8_t *bytes = guest_ptr(callsite, 4u);
    return bytes && decode_thumb_bl_target(
        callsite, ld16(bytes), ld16(bytes + 2u), target);
}

static bool kernel_symbol_bytes(const char *name, const uint8_t *expected,
                                size_t length, uint32_t *address) {
    uint32_t va = ksym_value(name) & ~1u;
    if (!va || !expected || !length || length > UINT32_MAX) return false;
    const uint8_t *actual = guest_ptr(va, (uint32_t)length);
    if (!actual || memcmp(actual, expected, length) != 0) return false;
    if (address) *address = va;
    return true;
}

/* Fetch bytes through the guest's current translation tables. guest_ptr()
 * intentionally handles only the kernel's fixed linear window, but the most
 * valuable undefined instructions now occur in user processes. Re-walk the
 * exact fetch mapping after a stop so the report always includes the encoding
 * that blocked progress. The stopped instruction already fetched once, so
 * this diagnostic read cannot introduce a mapping the guest did not use. */
static bool guest_fetch_bytes(uint32_t va, uint8_t *out, size_t n,
                              uint32_t *first_pa) {
    if (!g_mach || !out || n > UINT32_MAX ||
        (n && (uint64_t)va + n - 1u > UINT32_MAX)) return false;

    uint32_t mode = g_mach->cpu.cpsr & ARM_CPSR_MODE_MASK;
    bool priv = mode != ARM_MODE_USR;
    for (size_t i = 0; i < n; i++) {
        uint32_t pa = 0;
        uint32_t fsr = arm_mmu_translate(&g_mach->cpu, va + (uint32_t)i,
                                         ARM_ACCESS_FETCH, priv, &pa);
        if (fsr || pa < g_mach->ram_base) return false;
        uint64_t off = (uint64_t)pa - g_mach->ram_base;
        if (off >= g_mach->ram_size) return false;
        if (i == 0 && first_pa) *first_pa = pa;
        out[i] = g_mach->ram[(size_t)off];
    }
    return true;
}

/*
 * A lifecycle pathname is a USER virtual address, not a physical address and
 * not part of the kernel's fixed linear window.  Copy it while the caller's
 * TTBR0 is still live at _fleh_swi entry. Translate every byte: ARMv6 small
 * pages can apply different access permissions to their four 1 KiB subpages,
 * so one translation per 4 KiB page would not be fail-closed. The copy is
 * bounded to 256 bytes, making the extra diagnostic work negligible.
 *
 * The result is fail-closed: PATH_OK means a NUL was actually observed inside
 * the fixed bound.  Every other status leaves a terminated diagnostic prefix
 * but that prefix must never be treated as a pathname or used for detection.
 */
#define LIFECYCLE_PATH_MAX 256u

typedef enum {
    LIFECYCLE_PATH_NONE = 0,
    LIFECYCLE_PATH_OK,
    LIFECYCLE_PATH_NULL,
    LIFECYCLE_PATH_UNMAPPED,
    LIFECYCLE_PATH_NON_RAM,
    LIFECYCLE_PATH_WRAP,
    LIFECYCLE_PATH_NO_NUL,
    LIFECYCLE_PATH_INTERNAL
} lifecycle_path_status_t;

static bool guest_read_user_bytes(arm_cpu_t *cpu, uint32_t va,
                                  uint8_t *out, size_t length,
                                  uint32_t *failure_va,
                                  uint32_t *failure_fsr) {
    if (failure_va) *failure_va = 0;
    if (failure_fsr) *failure_fsr = 0;
    if (!cpu || !out || !length || !g_mach || !g_mach->ram || !va)
        return false;
    if ((uint64_t)va + length - 1u > UINT32_MAX) {
        if (failure_va) *failure_va = va;
        return false;
    }

    for (size_t i = 0; i < length; i++) {
        uint32_t current = va + (uint32_t)i;
        uint32_t pa = 0;
        uint32_t fsr = arm_mmu_translate(
            cpu, current, ARM_ACCESS_READ, false, &pa);
        if (fsr) {
            if (failure_va) *failure_va = current;
            if (failure_fsr) *failure_fsr = fsr;
            return false;
        }
        if (pa < g_mach->ram_base ||
            (uint64_t)pa - g_mach->ram_base >= g_mach->ram_size) {
            if (failure_va) *failure_va = current;
            return false;
        }
        out[i] = g_mach->ram[pa - g_mach->ram_base];
    }
    return true;
}

/* --- HLE: driving tools/ios3_hle.c from a real run ------------------------
 *
 * The library has been linkable and unit-tested for some time without any run
 * ever calling it, which made its sites unreachable instrumentation. This is
 * the seam that fixes that.
 *
 * WHICH ADDRESS SPACE. ios3_hle_arm() takes the TTBR0 sites are restricted to,
 * and a shared-cache address exists in every process, so that restriction is
 * load-bearing rather than decorative. SpringBoard's TTBR0 is not known until
 * it launches, so arming is deferred: the FIRST user-mode instruction that
 * lands exactly on a registered site selects the space, and everything arms to
 * it. That is self-configuring and needs no name resolution, but it is an
 * inference, so the chosen TTBR0 is printed in the report next to the hit
 * counts -- and any later hit from a different space is counted as wrong_space
 * rather than silently folded in. If those two disagree, the report says so.
 *
 * WRITES FAIL CLOSED. REPLACE sites use the writer below, which first translates
 * the complete range through the guest MMU and only then publishes bytes. A
 * fault therefore declines the native call without leaving a half-written
 * scanline for the guest implementation to inherit.
 */
/* Defined with the rest of the address-space diagnostics, far below. */
static uint32_t diagnostic_ttbr0_base(const arm_cpu_t *cpu);

static bool g_hle_enabled;
static bool g_hle_verify;
static uint32_t g_hle_space;     /* TTBR0 armed to; 0 == not armed yet */
static bool g_hle_pending;       /* a site failed identity and may yet arm */

#define HLE_VERIFY_SITE_MAX 32u
/* r276 observed more than 22,000 replaceable nested scanline/sampler calls in
 * the 3.9--4.4 B touch window. Keep the verifier exhaustive for that accepted
 * regression window instead of silently stopping before the interaction. */
#define HLE_VERIFY_LIMIT    65536u
#define HLE_VERIFY_DEPTH_MAX 8u
#define HLE_VERIFY_FULL_SCANLINE_BYTES 1280u
typedef struct {
    uint64_t begin_at[HLE_VERIFY_DEPTH_MAX];
    ios3_hle_oracle_t pending[HLE_VERIFY_DEPTH_MAX];
    uint8_t expected[HLE_VERIFY_DEPTH_MAX][IOS3_HLE_ORACLE_MAX_BYTES];
    unsigned depth;
    uint64_t attempts[HLE_VERIFY_SITE_MAX];
    uint64_t prepared[HLE_VERIFY_SITE_MAX];
    uint64_t passed[HLE_VERIFY_SITE_MAX];
    uint64_t mismatched[HLE_VERIFY_SITE_MAX];
    uint64_t unreadable[HLE_VERIFY_SITE_MAX];
    uint64_t prepared_total;
    unsigned pass_logs;
    unsigned full_scanline_pass_logs;
    unsigned failure_logs;
} hle_verify_state_t;
static hle_verify_state_t g_hle_verifier;

/*
 * WHY ARMING HAPPENS MORE THAN ONCE. Identity is verified by reading the
 * prologue out of guest memory, and a page that is not resident cannot be
 * read. Arming is triggered by the first site reached, which in r217 was
 * CoreGraphics' CGBlt_fillBytes -- and at that instant QuartzCore's rasteriser
 * pages had never been touched, so all three of those sites failed identity
 * and, with one-shot arming, stayed dead for the whole run while the profile
 * insisted they were 39.8% of a frame.
 *
 * The retry condition is the one that cannot be wrong: a site whose address
 * the PC has just arrived at is resident by definition, because the next thing
 * that happens is executing it. ios3_hle_arm() re-verifies every site from
 * scratch and leaves the hit counters alone, so re-calling it is safe.
 */
static void hle_note_pending(void) {
    g_hle_pending = false;
    for (unsigned i = 0; i < ios3_hle_site_count(); i++) {
        const ios3_hle_site_t *s = ios3_hle_site_at(i);
        if (s && !s->armed) { g_hle_pending = true; return; }
    }
}

/*
 * ARMv6 legacy small pages may assign different access permissions to each
 * 1 KiB subpage, and tiny pages are themselves 1 KiB.  That is therefore the
 * largest interval for which one successful translation proves both access
 * and a contiguous physical mapping.  Staying inside it removes hundreds of
 * thousands of redundant translations from a full-screen HLE publication
 * without weakening the bytewise path's fail-closed permission semantics.
 */
#define HLE_USER_MMU_CHUNK_BYTES 1024u

static uint32_t hle_user_mmu_chunk(uint32_t va, uint32_t remaining) {
    uint32_t to_boundary = HLE_USER_MMU_CHUNK_BYTES -
                           (va & (HLE_USER_MMU_CHUNK_BYTES - 1u));
    return remaining < to_boundary ? remaining : to_boundary;
}

static bool hle_mem_read(void *ctx, uint32_t va, void *dst, uint32_t len) {
    arm_cpu_t *cpu = (arm_cpu_t *)ctx;
    uint8_t *out = (uint8_t *)dst;

    if (!cpu || !out || !len || !g_mach || !g_mach->ram || !va)
        return false;
    if ((uint64_t)va + len > UINT64_C(0x100000000)) return false;

    for (uint32_t done = 0; done < len;) {
        uint32_t current = va + done;
        uint32_t chunk = hle_user_mmu_chunk(current, len - done);
        uint32_t pa = 0;
        if (arm_mmu_translate(cpu, current, ARM_ACCESS_READ, false, &pa))
            return false;
        if (pa < g_mach->ram_base ||
            (uint64_t)pa - g_mach->ram_base + chunk > g_mach->ram_size)
            return false;
        memcpy(out + done, g_mach->ram + (pa - g_mach->ram_base), chunk);
        done += chunk;
    }
    return true;
}

/*
 * The privileged read. See ios3_hle_mem_t::read_priv for why it exists and for
 * the rule it does NOT relax: pixels still go through the unprivileged path.
 * This translates with privilege so a kernel-side descriptor -- an IOSurface
 * the device itself reads -- can be inspected, and it is read-only.
 */
/*
 * A physical read, for descriptor-supplied addresses. See
 * ios3_hle_mem_t::read_phys. Serves guest DRAM and the MBX aperture's edram,
 * which are the only two regions a surface can live in, and refuses anything
 * else rather than inventing bytes for a device window.
 */
static bool hle_mem_read_phys(void *ctx, uint32_t pa, void *dst, uint32_t len) {
    uint8_t *out = (uint8_t *)dst;
    (void)ctx;

    if (!out || !len || !g_mach) return false;
    if ((uint64_t)pa + len - 1u > UINT32_MAX) return false;

    if (g_mach->ram && pa >= g_mach->ram_base &&
        (uint64_t)pa - g_mach->ram_base + len <= g_mach->ram_size) {
        memcpy(out, g_mach->ram + (pa - g_mach->ram_base), len);
        return true;
    }
    if (g_mach->mbx.edram && pa >= S5L8900_MBX_BASE + S5L_MBX_SIZE &&
        (uint64_t)pa - (S5L8900_MBX_BASE + S5L_MBX_SIZE) + len
            <= S5L_MBX_EDRAM_SIZE) {
        memcpy(out, g_mach->mbx.edram +
                    (pa - (S5L8900_MBX_BASE + S5L_MBX_SIZE)), len);
        return true;
    }
    return false;
}

static bool hle_mem_read_priv(void *ctx, uint32_t va, void *dst, uint32_t len) {
    arm_cpu_t *cpu = (arm_cpu_t *)ctx;
    uint8_t *out = (uint8_t *)dst;

    if (!cpu || !out || !len || !g_mach || !g_mach->ram || !va) return false;
    if ((uint64_t)va + len - 1u > UINT32_MAX) return false;

    for (uint32_t i = 0; i < len; i++) {
        uint32_t pa = 0;
        if (arm_mmu_translate(cpu, va + i, ARM_ACCESS_READ, true, &pa))
            return false;
        /* The same DRAM bound guest_read_user_bytes applies, for the same
         * reason: anything that is not plain RAM is a device, and a device
         * read is a side effect this must never cause. */
        if (pa < g_mach->ram_base ||
            (uint64_t)pa - g_mach->ram_base >= g_mach->ram_size)
            return false;
        out[i] = g_mach->ram[pa - g_mach->ram_base];
    }
    return true;
}

/*
 * The write half is UNPRIVILEGED and goes through the MMU one proven 1 KiB
 * mapping interval at a time. It may memcpy only inside that interval; crossing
 * one without translating again could skip an ARMv6 subpage permission change
 * or assume that two independently mapped physical pages are adjacent.
 *
 * Contract item 4 is the reason. A pixel buffer is a user virtual address and
 * is NOT guaranteed physically contiguous, so a host memcpy across a buffer
 * that spans two non-adjacent frames would corrupt whatever follows the first.
 * The complete transaction is still preflighted before publication. The
 * second walk observes the identical CPU/page-table state immediately after
 * preflight, with no guest instruction between the two passes.
 *
 * ANY refusal returns false rather than writing part of the range, because a
 * partial write is the one outcome that is worse than declining: the handler
 * would report failure while the guest's buffer already held half a result.
 * A caller that gets false must decline the whole call and let the guest run
 * its own code, which is contract item 5.
 */
static bool hle_mem_writev(void *ctx, const ios3_hle_write_span_t *spans,
                           uint32_t count) {
    arm_cpu_t *cpu = (arm_cpu_t *)ctx;

    if (!cpu || !spans || count == 0u ||
        count > IOS3_HLE_ORACLE_MAX_SPANS || !g_mach || !g_mach->ram)
        return false;

    /*
     * Translate EVERY range before storing a single byte. Checking row by row
     * would leave an upper prefix written when a later row faults, which is
     * the partial polygon this interface exists to forbid.
     */
    for (uint32_t s = 0; s < count; s++) {
        if (!spans[s].src || spans[s].len == 0u || !spans[s].va ||
            (uint64_t)spans[s].va + spans[s].len > UINT64_C(0x100000000))
            return false;
        for (uint32_t done = 0; done < spans[s].len;) {
            uint32_t current = spans[s].va + done;
            uint32_t chunk = hle_user_mmu_chunk(
                current, spans[s].len - done);
            uint32_t pa = 0;
            if (arm_mmu_translate(cpu, current, ARM_ACCESS_WRITE, false, &pa))
                return false;
            if (pa < g_mach->ram_base ||
                (uint64_t)pa - g_mach->ram_base + chunk > g_mach->ram_size)
                return false;
            done += chunk;
        }
    }

    for (uint32_t s = 0; s < count; s++) {
        const uint8_t *bytes = (const uint8_t *)spans[s].src;
        for (uint32_t done = 0; done < spans[s].len;) {
            uint32_t current = spans[s].va + done;
            uint32_t chunk = hle_user_mmu_chunk(
                current, spans[s].len - done);
            uint32_t pa = 0;
            (void)arm_mmu_translate(cpu, current, ARM_ACCESS_WRITE, false, &pa);
            memcpy(g_mach->ram + (pa - g_mach->ram_base), bytes + done, chunk);
            done += chunk;
        }
    }
    return true;
}

static bool hle_mem_write(void *ctx, uint32_t va, const void *src,
                          uint32_t len) {
    ios3_hle_write_span_t span = { va, src, len };
    return hle_mem_writev(ctx, &span, 1u);
}

static bool hle_prepare(arm_cpu_t *cpu, ios3_hle_mem_t *mem,
                        uint32_t *pc_out, uint32_t *as_out) {
    uint32_t as, pc;
    if (!g_hle_enabled || !cpu) return false;
    if ((cpu->cpsr & ARM_CPSR_MODE_MASK) != ARM_MODE_USR) return false;

    mem->ctx = cpu;
    mem->read = hle_mem_read;
    mem->write = hle_mem_write;
    mem->read_priv = hle_mem_read_priv;
    mem->read_phys = hle_mem_read_phys;
    mem->writev = hle_mem_writev;
    as = diagnostic_ttbr0_base(cpu);
    pc = cpu->r[15] & ~1u;

    if (!g_hle_space) {
        for (unsigned i = 0; i < ios3_hle_site_count(); i++) {
            const ios3_hle_site_t *s = ios3_hle_site_at(i);
            if (s && s->va == pc) {
                if (ios3_hle_arm(mem, as)) {
                    g_hle_space = as;
                    hle_note_pending();
                }
                break;
            }
        }
        if (!g_hle_space) return false;
    } else if (g_hle_pending && as == g_hle_space) {
        /* Only while something is still unarmed, so the common case stays a
         * single predictable branch rather than a scan of the whole table. */
        for (unsigned i = 0; i < ios3_hle_site_count(); i++) {
            const ios3_hle_site_t *s = ios3_hle_site_at(i);
            if (s && !s->armed && s->va == pc) {
                ios3_hle_arm(mem, g_hle_space);
                hle_note_pending();
                break;
            }
        }
    }
    if (pc_out) *pc_out = pc;
    if (as_out) *as_out = as;
    return true;
}

/*
 * Returns true only when a handler did the whole job and set the CPU up to
 * return, in which case the caller must NOT step this instruction. OBSERVE and
 * TRACE sites still return false; a REPLACE handler that cannot prove its
 * argument shape or complete every access also returns false and the guest runs
 * the original routine.
 */
static bool hle_took_call(arm_cpu_t *cpu) {
    ios3_hle_mem_t mem;
    uint32_t as, pc;
    if (!hle_prepare(cpu, &mem, &pc, &as)) return false;
    return ios3_hle_step(cpu, &mem, pc, as);
}

/* Prepare a native result without publishing it. A bounded LIFO is necessary:
 * sw_scanline calls a nearest sampler, and verifying only the outer return
 * would leave the leaf replacements unproved. Guest calls nest in return order,
 * so the top expected span is always the first one eligible to compare. */
static void hle_verify_begin(arm_cpu_t *cpu, uint64_t at) {
    ios3_hle_mem_t mem;
    ios3_hle_oracle_t candidate;
    uint32_t as, pc, index;
    bool ready;

    if (!g_hle_verify || g_hle_verifier.depth >= HLE_VERIFY_DEPTH_MAX ||
        g_hle_verifier.prepared_total >= HLE_VERIFY_LIMIT)
        return;
    if (!hle_prepare(cpu, &mem, &pc, &as)) return;

    ready = ios3_hle_oracle_prepare(
        cpu, &mem, pc, as, &candidate,
        g_hle_verifier.expected[g_hle_verifier.depth],
        (uint32_t)sizeof g_hle_verifier.expected[g_hle_verifier.depth]);
    if (candidate.site_index == UINT32_MAX) return;
    index = candidate.site_index;
    if (index >= HLE_VERIFY_SITE_MAX) {
        if (g_hle_verifier.failure_logs++ == 0u)
            fprintf(stderr,
                    "hle-verify: site index %u exceeds verifier capacity %u\n",
                    index, HLE_VERIFY_SITE_MAX);
        return;
    }
    g_hle_verifier.attempts[index]++;
    if (!ready) return;

    g_hle_verifier.pending[g_hle_verifier.depth] = candidate;
    g_hle_verifier.begin_at[g_hle_verifier.depth] = at;
    g_hle_verifier.depth++;
    g_hle_verifier.prepared[index]++;
    g_hle_verifier.prepared_total++;
}

static void hle_verify_note_post_step(arm_cpu_t *cpu, uint64_t at) {
    uint8_t actual[4096];
    ios3_hle_oracle_t *expected;
    uint64_t begin_at;
    uint32_t index, bad_span = 0u, bad_offset = 0u;
    uint8_t native_byte = 0u, guest_byte = 0u;
    bool unreadable = false, mismatch = false;

    if (!g_hle_verify || g_hle_verifier.depth == 0u || !cpu)
        return;
    expected = &g_hle_verifier.pending[g_hle_verifier.depth - 1u];
    begin_at = g_hle_verifier.begin_at[g_hle_verifier.depth - 1u];
    if ((cpu->cpsr & ARM_CPSR_MODE_MASK) != ARM_MODE_USR ||
        (g_hle_space && diagnostic_ttbr0_base(cpu) != g_hle_space) ||
        (cpu->r[15] & ~1u) != (expected->return_pc & ~1u) ||
        cpu->r[13] != expected->return_sp)
        return;

    index = expected->site_index;
    for (uint32_t s = 0; s < expected->span_count && !unreadable && !mismatch;
         s++) {
        const ios3_hle_oracle_span_t *span = &expected->spans[s];
        for (uint32_t offset = 0; offset < span->len;) {
            uint32_t left = span->len - offset;
            uint32_t chunk = left < sizeof actual ? left
                                                  : (uint32_t)sizeof actual;
            const uint8_t *native = expected->expected +
                                    span->expected_offset + offset;
            if (!hle_mem_read(cpu, span->va + offset, actual, chunk)) {
                unreadable = true;
                bad_span = s;
                bad_offset = offset;
                break;
            }
            for (uint32_t i = 0; i < chunk; i++) {
                if (actual[i] != native[i]) {
                    mismatch = true;
                    bad_span = s;
                    bad_offset = offset + i;
                    native_byte = native[i];
                    guest_byte = actual[i];
                    break;
                }
            }
            if (mismatch) break;
            offset += chunk;
        }
    }

    if (unreadable) {
        g_hle_verifier.unreadable[index]++;
        if (g_hle_verifier.failure_logs++ < 8u)
            fprintf(stderr,
                    "hle-verify UNREADABLE %s spans=%u bytes=%u "
                    "at=%08x+%u begin=%llu return=%llu\n",
                    expected->site_name, expected->span_count,
                    expected->expected_len, expected->spans[bad_span].va,
                    bad_offset,
                    (unsigned long long)begin_at,
                    (unsigned long long)at);
    } else if (mismatch) {
        g_hle_verifier.mismatched[index]++;
        if (g_hle_verifier.failure_logs++ < 8u)
            fprintf(stderr,
                    "hle-verify MISMATCH %s spans=%u bytes=%u "
                    "span=%u at=%08x+%u "
                    "native=%02x guest=%02x begin=%llu return=%llu\n",
                    expected->site_name, expected->span_count,
                    expected->expected_len, bad_span,
                    expected->spans[bad_span].va, bad_offset,
                    native_byte, guest_byte,
                    (unsigned long long)begin_at,
                    (unsigned long long)at);
    } else {
        g_hle_verifier.passed[index]++;
        if (g_hle_verifier.pass_logs++ < 12u ||
            (expected->site_name &&
             strcmp(expected->site_name, "sw_scanline") == 0 &&
             expected->span_count == 1u &&
             expected->spans[0].len == HLE_VERIFY_FULL_SCANLINE_BYTES &&
             g_hle_verifier.full_scanline_pass_logs++ < 4u)) {
            if (expected->span_count == 1u)
                printf("hle-verify PASS %s span=%08x+%u "
                       "begin=%llu return=%llu\n",
                       expected->site_name, expected->spans[0].va,
                       expected->spans[0].len,
                       (unsigned long long)begin_at,
                       (unsigned long long)at);
            else
                printf("hle-verify PASS %s spans=%u bytes=%u "
                       "first=%08x+%u begin=%llu return=%llu\n",
                       expected->site_name, expected->span_count,
                       expected->expected_len, expected->spans[0].va,
                       expected->spans[0].len,
                       (unsigned long long)begin_at,
                       (unsigned long long)at);
        }
    }
    g_hle_verifier.depth--;
}

static lifecycle_path_status_t
guest_copy_user_cstr(arm_cpu_t *cpu, uint32_t va,
                     char out[LIFECYCLE_PATH_MAX + 1u],
                     uint16_t *length, uint32_t *failure_va,
                     uint32_t *failure_fsr) {
    size_t copied = 0;

    if (length) *length = 0;
    if (failure_va) *failure_va = 0;
    if (failure_fsr) *failure_fsr = 0;
    if (!out) return LIFECYCLE_PATH_INTERNAL;
    out[0] = '\0';
    if (!cpu || !g_mach || !g_mach->ram) return LIFECYCLE_PATH_INTERNAL;
    if (!va) return LIFECYCLE_PATH_NULL;

    while (copied < LIFECYCLE_PATH_MAX) {
        uint64_t current64 = (uint64_t)va + copied;
        if (current64 > UINT32_MAX) {
            if (failure_va) *failure_va = UINT32_MAX;
            out[copied] = '\0';
            if (length) *length = (uint16_t)copied;
            return LIFECYCLE_PATH_WRAP;
        }

        uint32_t current = (uint32_t)current64;
        uint32_t pa = 0;
        uint32_t fsr = arm_mmu_translate(cpu, current, ARM_ACCESS_READ,
                                         false, &pa);
        if (fsr) {
            if (failure_va) *failure_va = current;
            if (failure_fsr) *failure_fsr = fsr;
            out[copied] = '\0';
            if (length) *length = (uint16_t)copied;
            return LIFECYCLE_PATH_UNMAPPED;
        }
        if (pa < g_mach->ram_base) {
            if (failure_va) *failure_va = current;
            out[copied] = '\0';
            if (length) *length = (uint16_t)copied;
            return LIFECYCLE_PATH_NON_RAM;
        }

        uint64_t off = (uint64_t)pa - g_mach->ram_base;
        if (off >= g_mach->ram_size) {
            if (failure_va) *failure_va = current;
            out[copied] = '\0';
            if (length) *length = (uint16_t)copied;
            return LIFECYCLE_PATH_NON_RAM;
        }

        uint8_t byte = g_mach->ram[(size_t)off];
        if (!byte) {
            out[copied] = '\0';
            if (length) *length = (uint16_t)copied;
            return LIFECYCLE_PATH_OK;
        }
        out[copied++] = (char)byte;
    }

    out[copied] = '\0';
    if (length) *length = (uint16_t)copied;
    return LIFECYCLE_PATH_NO_NUL;
}

/* Print the C string at a guest address, escaped, or say why we cannot. */
static void print_guest_str(const char *label, uint32_t va) {
    const uint8_t *p = guest_ptr(va, 1);
    if (!p) { printf("  %s 0x%08x -> (not in RAM)\n", label, va); return; }
    printf("  %s 0x%08x -> \"", label, va);
    for (unsigned i = 0; i < 400 && p[i]; i++) {
        uint8_t c = p[i];
        if (c == '\n') printf("\\n");
        else if (c == '\t') printf("\\t");
        else if (c >= 0x20 && c < 0x7f) putchar((char)c);
        else printf("\\x%02x", c);
    }
    printf("\"\n");
}

/* ---------------------------------------------------------------------------
 * The guest's OWN view of memory.
 *
 * The budget printed in the header is the host's arithmetic. This is the
 * kernel's answer to the same question, read straight out of its globals, and
 * the two disagreeing is itself information (it would mean the kernel is not
 * seeing the DRAM we think we gave it).
 *
 * vm_page_free_count is a PAGE count, sampled rather than watched: the number
 * that matters for "does a 92 MB shared cache fit" is not the value at the end
 * of the run but the LOW-WATER MARK across it, because a boot that survives on
 * average and runs out once still dies. Sampling is on the same phase as the
 * profiler, so it costs four guest reads per 64K instructions.
 *
 * All of these are plain kernel-window globals, so guest_ptr's linear
 * translation reaches them without an MMU walk. A symbol that does not resolve
 * reads as 0 and prints as "-", never as a plausible wrong number.
 * ------------------------------------------------------------------------- */
static uint32_t guest_u32(uint32_t va) {
    const uint8_t *p = va ? guest_ptr(va, 4) : NULL;
    return p ? ld32(p) : 0u;
}

static struct {
    uint32_t free_va, wire_va, active_va, inactive_va, target_va;
    uint32_t sane_va, maxmem_va, memsize_va;
    uint32_t availstart_va, availend_va, firstavail_va;
    uint32_t free_peak;         /* most free pages ever seen = end of bootstrap */
    uint64_t free_peak_at;
    uint32_t free_min;          /* low-water mark AFTER the peak, in pages */
    uint64_t free_min_at;       /* absolute instruction index of that minimum */
    uint32_t free_first;        /* first non-zero sample */
    uint64_t free_first_at;
    uint64_t samples;
    uint64_t hist[40];          /* free-page sums over the run, 40 buckets */
    uint64_t hist_n[40];
} VM;

static void vm_resolve(void) {
    VM.free_va       = ksym_value("_vm_page_free_count");
    VM.wire_va       = ksym_value("_vm_page_wire_count");
    VM.active_va     = ksym_value("_vm_page_active_count");
    VM.inactive_va   = ksym_value("_vm_page_inactive_count");
    VM.target_va     = ksym_value("_vm_page_free_target");
    VM.sane_va       = ksym_value("_sane_size");
    VM.maxmem_va     = ksym_value("_max_mem");
    VM.memsize_va    = ksym_value("_mem_size");
    VM.availstart_va = ksym_value("_avail_start");
    VM.availend_va   = ksym_value("_avail_end");
    VM.firstavail_va = ksym_value("_first_avail");
    VM.free_min = 0xffffffffu;
}

static void vm_sample(uint64_t n, uint64_t steps) {
    if (!VM.free_va) return;
    uint32_t f = guest_u32(VM.free_va);
    /* Zero means vm_page_bootstrap has not run yet, not "out of memory". */
    if (!f) return;
    VM.samples++;
    if (!VM.free_first) { VM.free_first = f; VM.free_first_at = n; }
    /*
     * The low-water mark is only meaningful AFTER the pool is full.
     * vm_page_bootstrap fills the free list one page at a time, so the first
     * samples catch it mid-fill and a naive minimum reports "0.38 MB free",
     * which reads as catastrophic memory pressure and is nothing of the kind.
     * Track the peak, and only start looking for a minimum once past it.
     */
    if (f >= VM.free_peak) { VM.free_peak = f; VM.free_peak_at = n; VM.free_min = f; }
    else if (f < VM.free_min) { VM.free_min = f; VM.free_min_at = n; }
    unsigned b = instruction_bucket(n, steps);
    VM.hist[b] += f;
    VM.hist_n[b]++;
}

#define VM_MB(pages) ((double)(pages) * 4096.0 / 1048576.0)

static void vm_report(void) {
    printf("\n=== GUEST VM COUNTERS (the kernel's own view) ===\n");
    if (!VM.free_va) {
        printf("    _vm_page_free_count did not resolve — no report\n");
        return;
    }
    struct { const char *nm; uint32_t va; bool pages; } row[] = {
        { "mem_size",              VM.memsize_va,    false },
        { "max_mem",               VM.maxmem_va,     false },
        { "sane_size",             VM.sane_va,       false },
        { "avail_start",           VM.availstart_va, false },
        { "avail_end",             VM.availend_va,   false },
        { "first_avail",           VM.firstavail_va, false },
        { "vm_page_free_count",    VM.free_va,       true  },
        { "vm_page_free_target",   VM.target_va,     true  },
        { "vm_page_wire_count",    VM.wire_va,       true  },
        { "vm_page_active_count",  VM.active_va,     true  },
        { "vm_page_inactive_count",VM.inactive_va,   true  },
    };
    for (unsigned i = 0; i < sizeof row / sizeof row[0]; i++) {
        if (!row[i].va) { printf("    %-24s -\n", row[i].nm); continue; }
        uint32_t v = guest_u32(row[i].va);
        if (row[i].pages)
            printf("    %-24s %10u pages  %8.2f MB\n", row[i].nm, v, VM_MB(v));
        else
            printf("    %-24s 0x%08x       %8.2f MB\n", row[i].nm, v, v / 1048576.0);
    }
    if (VM.samples) {
        printf("    ---- free pages over the run (%" PRIu64 " samples) ----\n",
               VM.samples);
        printf("    first  %8u pages %7.2f MB  @instr %" PRIu64
               "  (mid-bootstrap)\n",
               VM.free_first, VM_MB(VM.free_first), VM.free_first_at);
        printf("    peak   %8u pages %7.2f MB  @instr %" PRIu64
               "  (pool fully built)\n",
               VM.free_peak, VM_MB(VM.free_peak), VM.free_peak_at);
        printf("    LOWEST %8u pages %7.2f MB  @instr %" PRIu64
               "   <-- the headroom "
               "that actually has to hold everything\n",
               VM.free_min, VM_MB(VM.free_min), VM.free_min_at);
        for (unsigned i = 0; i < 40; i++)
            if (VM.hist_n[i])
                printf("      bucket %2u  mean free %8.2f MB\n",
                       i, VM_MB((double)VM.hist[i] / (double)VM.hist_n[i]));
    } else {
        printf("    (never sampled non-zero — vm_page_bootstrap not reached)\n");
    }
}

/* ------------------------------------------------------------------------
 * DIAGNOSTIC INSTRUMENTATION (temporary; for finding the serial console).
 *
 * Two questions we cannot answer from outside:
 *   1. Does the kernel ever touch the UART page at all?
 *   2. How far down XNU's console-init chain does it actually get?
 *
 * (1) is answered by wrapping the bus callbacks — bootkernel owns the
 *     arm_bus_t after s5l8900_init(), so it can interpose without touching
 *     the core. Note that with the MMU on, an access to an *unmapped virtual*
 *     address aborts inside the MMU and never reaches the bus, which is why
 *     "zero unmapped physical accesses" proves nothing on its own.
 *
 * (2) is answered by watching the PC for the addresses of the pexpert
 *     functions in the console path, taken from the kernel's own symbol
 *     table (xnu-1357.5.30, iPhone1,2 7E18). Each is matched both at its
 *     virtual address and at the physical alias it has before the MMU is on.
 * ---------------------------------------------------------------------- */
#define UARTPG 0x3cc00000u
/*
 * uart4, the PPP line. A separate page and a separate tee, because the two
 * streams answer different questions and splicing them would destroy both
 * answers: this one is a byte stream with no line structure, and the only
 * thing that makes a byte on it meaningful is that it came from THIS port.
 */
#define UART4PG 0x3cc10000u

typedef struct { const char *name; uint32_t va; } milestone_t;

/* Virtual addresses from the kernelcache symbol table (thumb bit cleared). */
static const milestone_t MILESTONES[] = {
    { "_arm_init_cpu",              0xc0062c58u },
    { "_arm_vm_init",               0xc0062d60u },
    { "_DTInit",                    0xc01a7474u },
    { "_PE_init_platform",          0xc01a83ecu },
    { "_pe_identify_machine",       0xc01a7f1cu },
    { "_pe_arm_get_soc_base_phys",  0xc01a7c5cu },
    { "_PE_parse_boot_argn",        0xc01a7a5au },
    { "_PE_init_kprintf",           0xc01a8840u },
    { "_serial_init",               0xc01a8a78u },
    { "serial_init:soc_base_call",  0xc01a8af4u },
    { "serial_init:RET0_no_soc",    0xc01a8afcu },
    { "serial_init:found_node",     0xc01a8b84u },
    { "serial_init:ml_io_map_call", 0xc01a8ba4u },
    { "serial_init:RET1_ok",        0xc01a8b78u },
    { "_ml_io_map",                 0xc006963cu },
    { "_DTFindEntry",               0xc01a7738u },
    { "_DTGetProperty",             0xc01a7620u },
    { "_uart_putc",                 0xc01a89d4u },
    { "uart_putc:past_init_gate",   0xc01a89f0u },
    { "_serial_putc",               0xc01a87f2u },
    { "_kprintf",                   0xc01a880cu },
    { "_cnputc",                    0xc006d342u },
    { "_conslog_putc",              0xc002290cu },
    { "_switch_to_serial_console",  0xc005f018u },
    { "_initialize_screen",         0xc0070380u },
    { "_PE_initialize_console",     0xc01a85f0u },
    { "_machine_startup",           0xc0209a40u },
    { "_kernel_bootstrap",          0xc020862cu },
    { "_bsd_init",                  0xc020ae14u },
    /* The M5 frontier: pid 1 exec'ing /sbin/launchd, and what it hits on the
     * way. grade_binary is the gate that used to answer 0 — CPU_SUBTYPE_ARM_ALL
     * against an ARMv6 Mach-O — and turn the exec into EBADARCH. The rest say
     * whether we then get past code signing (cs_validate_page / ubc_cs_blob_add)
     * and the MAC policy (mac_vnode_check_exec), and whether the new image ever
     * reaches user mode (thread_bootstrap_return) and issues a system call. */
    { "_load_init_program",         0xc011d9acu },
    { "_execve",                    0xc011d98cu },
    { "_load_machfile",             0xc014c508u },
    { "_grade_binary",              0xc0153f90u },
    { "_mac_vnode_check_exec",      0xc01acb38u },
    { "_ubc_cs_blob_add",           0xc013b2a4u },
    { "_cs_validate_page",          0xc013af54u },
    { "_thread_bootstrap_return",   0xc006871cu },
    { "_unix_syscall",              0xc01541a8u },
    { "_bsdinit_task",              0xc0110868u },
    /* Which exception the userspace image is actually taking. A first-level
     * handler count that climbs without _unix_syscall ever being reached means
     * pid 1 is spinning on a fault rather than making progress. */
    { "_fleh_swi",                  0xc00680a0u },
    { "_fleh_undef",                0xc0067ff8u },
    { "_fleh_prefabt",              0xc006828cu },
    { "_fleh_dataabt",              0xc0068338u },
    { "_sleh_undef",                0xc006c184u },
    { "_sleh_abort",                0xc006c538u },
    { "_vm_fault",                  0xc003e6f0u },
    { "_exception_triage",          0xc001c708u },
    { "_mach_msg_overwrite_trap",   0xc001899cu },
    { "_cs_invalid_page",           0xc0121e5eu },
    { "_psignal",                   0xc0127278u },
    { "_exit1",                     0xc011f63cu },
    /* Three PCs inside cs_validate_page (0xc013af54), which is the verdict on
     * one page of a signed executable. They separate the three ways it can say
     * no, and only one of them is our bug:
     *   no_hash_exit  0xc013b11a — no blob covers this page, or the code
     *                              directory has no hash slot for it: policy.
     *   hashing       0xc013b0ca — SHA1Init, i.e. it found a hash and is about
     *                              to compute the page's own.
     *   bad_hash      0xc013b0f8 — the bcmp failed. The page we handed the
     *                              kernel is not the page the signature was
     *                              made over, which is a data-path bug on our
     *                              side, not a signing policy we can opt out of. */
    { "cs_validate:no_hash_exit",   0xc013b11au },
    { "cs_validate:hashing",        0xc013b0cau },
    { "cs_validate:bad_hash",       0xc013b0f8u },
    { "_panic",                     0xc001c13cu },
    { "_Debugger",                  0xc006abbcu },
};
#define NMILE ((unsigned)(sizeof MILESTONES / sizeof MILESTONES[0]))

/*
 * Milestones resolved BY NAME out of the kernel's own symbol table instead of
 * being hand-transcribed. Everything here answers one question — "is the
 * machine still doing work, or has every thread parked?" — so the list is the
 * scheduler, the sleep primitives, the Mach IPC receive path, and the two
 * dyld-facing syscalls that a launchd which cannot map the shared cache would
 * be stuck at. A name that does not resolve is dropped silently at startup and
 * reported in the milestone table by its absence, never by a wrong address.
 */
static const char *MILE_BYNAME[] = {
    /* scheduler / idle: if these are the whole late window, nothing is runnable */
    "_machine_idle", "_idle_thread", "_thread_block_reason", "_thread_invoke",
    "_thread_continue", "_thread_go", "_swtch", "_thread_switch",
    "_wait_queue_assert_wait", "_clock_delay_until", "_delay",
    /* BSD sleep */
    "_msleep", "_tsleep", "_tsleep0", "_msleep0",
    /* Mach IPC receive — a launchd blocked on a port sits here */
    "_mach_msg_trap", "_ipc_mqueue_receive", "_ipc_mqueue_receive_continue",
    "_semaphore_wait_continue",
    /* the dyld shared cache path */
    "_shared_region_map_np", "_shared_region_check_np",
    /* VM / exec paths worth seeing counts for */
    "_mmap", "_vm_map_enter", "_kernel_thread_start",
};
#define NMILE_BYNAME ((unsigned)(sizeof MILE_BYNAME / sizeof MILE_BYNAME[0]))
#define NMILE_MAX (NMILE + NMILE_BYNAME)

/* The runtime table actually scanned by the step loop: the hand-written list
 * above followed by whichever of MILE_BYNAME the symbol table could resolve. */
static milestone_t MILE[NMILE_MAX];
static unsigned    NM;

#define LIFECYCLE_CAP 256u
#define DEFAULT_HOT_PAGE UINT32_C(0x39a00000)
/*
 * -H is repeatable. It used to store a single page and the second occurrence
 * silently replaced the first, which is the worst possible behaviour for a
 * diagnostic: a run asked to watch two blocks watched one and said nothing.
 * Four is enough to cover a controller, its interrupt controller and two
 * neighbours without making the per-register tables unreadable.
 */
#define HOT_PAGE_MAX 4u

/*
 * Where the lossless console tee lands. A fixed relative name, resolved
 * against the process working directory exactly as `firmware/screen.ppm`
 * already is, so tools/run23-cold-replay.ps1's -WorkingDirectory puts it in
 * the run directory beside the run's other outputs with no new option to pass.
 */
#define UART_TEE_PATH "uart-console.log"

/*
 * And where uart4's stream lands. Binary, and named .bin rather than .log, for
 * a reason that is not cosmetic: PPP is HDLC-framed and its escape byte is
 * 0x7D, so a stream opened in text mode on this host would have every 0x0A
 * inside a frame rewritten to CR LF and the capture would no longer be the
 * bytes the guest sent. That is the whole value of the file.
 */
#define PPP_TEE_PATH "uart4-ppp.bin"

/*
 * The milestone, byte for byte.
 *
 *   7E     flag, start of frame                       (RFC 1662 4.1)
 *   FF     all-stations address                       (RFC 1662 4.2)
 *   7D 23  the UI control byte 0x03, escaped: pppd has not yet negotiated
 *          ACCOMP, and 0x03 is below 0x20 so the default async control
 *          character map requires 0x7D followed by 0x03 ^ 0x20
 *   C0 21  protocol identifier 0xC021, LCP            (RFC 1661 2)
 *
 * Six bytes and nothing more, because everything after them varies: the code,
 * identifier and length are followed by pppd 2.4.2's default first request --
 * MRU 1500, ASYNCMAP 0x00000000, a RANDOM magic number, PCOMP and ACCOMP --
 * and pinning the magic number would make the check fail on every run but one.
 *
 * Seeing this prefix on uart4 is the S0 milestone, and it proves nine things
 * at once that are otherwise separately unobservable: the DMA skip took, the
 * serial driver bound the nub, the devfs node carries the name we predicted,
 * the plist hijack survived into the work image, launchd started the job, AMFI
 * accepted Apple-signed pppd, dyld loaded its frameworks, the tty opened, and
 * the pppserial line discipline attached. Anything less than these exact bytes
 * is not the milestone.
 */
static const uint8_t PPP_LCP_CONFREQ[6] = {
    0x7eu, 0xffu, 0x7du, 0x23u, 0xc0u, 0x21u
};

