/*
 * Process-wide, diagnostic-only state for the exact CommCenter SETEXEC-attempt
 * identity. The tuple comes from its pathname-qualified lifecycle event, never
 * from a guessed PID. Per-instruction work is restricted to a cached thread
 * comparison and, only while execution is attributed to that identity,
 * bounded counter and last-sample updates.
 */
typedef struct {
    bool armed;
    bool terminal;
    bool identity_invalidated;
    bool current_classified;
    bool current_matches;
    bool initial_send_queue_entry_seen;
    bool receiver_seen;
    bool receiver_complete;
    bool receiver_matches;
    bool receiver_is_launchd;
    uint64_t generation;
    uint64_t armed_at;
    uint64_t initial_send_queue_entry_at;
    uint64_t current_next_unreadable_retry_at;
    uint64_t identity_unreadable_classifications;
    uint64_t identity_mismatch_switches;
    uint64_t exact_setexec_attempts;
    uint64_t ignored_distinct_attempts;
    uint64_t last_ignored_distinct_attempt_at;
    uint64_t user_returns[COMMCENTER_WATCH_PHASE_COUNT];
    uint64_t instructions[COMMCENTER_WATCH_PHASE_COUNT]
                         [COMMCENTER_WATCH_MODE_COUNT];
    uint64_t switch_total;
    uint64_t mach_total;
    uint64_t mach_send[COMMCENTER_WATCH_PHASE_COUNT];
    uint64_t mach_receive[COMMCENTER_WATCH_PHASE_COUNT];
    uint64_t mach_send_header_readable[COMMCENTER_WATCH_PHASE_COUNT];
    uint64_t wait_thread_overflow;
    uint64_t wait_exact_hook_attribution_omissions;
    uint64_t wait_exact_hook_first_omission_at;
    uint64_t wait_exact_hook_last_omission_at;
    uint64_t signal_count;
    uint64_t exit_count;
    uint64_t first_signal_at;
    uint64_t last_signal_at;
    uint64_t exit_at;
    uint32_t task;
    uint32_t proc;
    uint32_t pid;
    uint32_t entry_thread;
    uint32_t current_thread;
    uint32_t last_ignored_distinct_task;
    uint32_t last_ignored_distinct_proc;
    uint32_t last_ignored_distinct_pid;
    uint32_t first_signal;
    uint32_t last_signal;
    uint32_t exit_status;
    uint32_t identity_failure_va;
    uint32_t identity_failure_fsr;
    uint32_t wait_exact_hook_first_omission_pc;
    uint32_t wait_exact_hook_first_omission_thread;
    uint32_t wait_exact_hook_last_omission_pc;
    uint32_t wait_exact_hook_last_omission_thread;
    uint32_t receiver_name;
    uint32_t receiver_space;
    uint32_t receiver_task;
    uint32_t receiver_proc;
    uint32_t receiver_pid;
    uint32_t receiver_valid_bits;
    commcenter_watch_sample_t
        first[COMMCENTER_WATCH_PHASE_COUNT];
    commcenter_watch_sample_t
        last[COMMCENTER_WATCH_PHASE_COUNT];
    /*
     * User-mode-only attribution. The samples above are captured regardless of
     * mode, so in practice they report kernel PCs and say nothing about where
     * CommCenter's own code goes. Run24 made that the live question: five
     * daemons plus SpringBoard are queued behind a service that has never
     * checked in, and the baseband lead that might have explained it is dead.
     *
     * These fields are USR-mode only, and the region counters use the same
     * fixed boundaries the SpringBoard trace uses, so the two are comparable.
     */
    commcenter_watch_sample_t
        first_user[COMMCENTER_WATCH_PHASE_COUNT];
    commcenter_watch_sample_t
        last_user[COMMCENTER_WATCH_PHASE_COUNT];
    uint64_t user_region_hits[COMMCENTER_WATCH_USER_REGION_COUNT];
    uint64_t user_region_first_at[COMMCENTER_WATCH_USER_REGION_COUNT];
    uint64_t user_region_last_at[COMMCENTER_WATCH_USER_REGION_COUNT];
    uint32_t user_region_first_pc[COMMCENTER_WATCH_USER_REGION_COUNT];
    uint32_t user_region_last_pc[COMMCENTER_WATCH_USER_REGION_COUNT];
    /* Newest-retaining tail of user PCs: where it got to before parking. */
    uint64_t user_pc_total;
    commcenter_watch_sample_t
        user_pcs[COMMCENTER_WATCH_USER_PC_CAP];
    /* Exact imported-function stub sites; see COMMCENTER_IMAGE_CHECKPOINTS. */
    uint64_t image_checkpoint_hits[COMMCENTER_IMAGE_CHECKPOINT_COUNT];
    uint64_t image_checkpoint_first_at[COMMCENTER_IMAGE_CHECKPOINT_COUNT];
    uint64_t image_checkpoint_last_at[COMMCENTER_IMAGE_CHECKPOINT_COUNT];
    uint32_t image_checkpoint_lr[COMMCENTER_IMAGE_CHECKPOINT_COUNT];
    uint32_t image_checkpoint_thread[COMMCENTER_IMAGE_CHECKPOINT_COUNT];
    uint32_t image_checkpoint_r[COMMCENTER_IMAGE_CHECKPOINT_COUNT][4];
    commcenter_watch_switch_event_t
        switches[COMMCENTER_WATCH_SWITCH_CAP];
    commcenter_watch_mach_event_t
        mach[COMMCENTER_WATCH_MACH_CAP];
    commcenter_watch_milestone_observation_t
        milestones[COMMCENTER_WATCH_MILESTONE_COUNT];
    commcenter_thread_wait_t
        wait_threads[COMMCENTER_WAIT_THREAD_CAP];
} commcenter_watch_t;

